def _load_native_dll(name: str):
    """Load a DLL/so by bare name (system search), then CUDA toolkit paths,
    then the script's own folder."""
    try:
        return ctypes.CDLL(name)
    except OSError:
        pass
    # Search common CUDA toolkit locations for NVRTC/cuda runtime DLLs
    if os.name == 'nt':
        cuda_roots = []
        cuda_path = os.environ.get('CUDA_PATH')
        if cuda_path:
            cuda_roots.append(Path(cuda_path))
        for v in ['13.3', '12.9', '12.6', '12.5', '12.4', '12.3', '12.2', '12.1', '12.0', '11.8']:
            cuda_roots.append(Path(rf"C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v{v}"))
        for root in cuda_roots:
            for sub in ['bin', 'lib', 'lib/x64']:
                p = root / sub / name
                if p.exists():
                    return ctypes.CDLL(str(p))
        # Also try adding the CUDA bin dir to the DLL search path
        for root in cuda_roots:
            bin_dir = root / 'bin'
            if bin_dir.exists():
                try:
                    os.add_dll_directory(str(bin_dir))
                except (OSError, AttributeError):
                    pass
    local_path = _ENGINE_DIR / name
    if local_path.exists():
        return ctypes.CDLL(str(local_path))
    raise OSError(f"Could not locate {name}")


class StreamingDecoder:
    """Incremental UTF-8 decoder for streaming token text.

    Byte-level tokenizers (GPT-2 style, Gemma/LLaMA byte fallbacks) can
    split a single multi-byte UTF-8 character across two tokens.  Decoding
    each piece independently with decode_single() then yields broken
    replacement characters ('\ufffd').  This decoder keeps the incremental
    buffer across tokens so split codepoints reassemble correctly.
    """

    def __init__(self):
        self._decoder = codecs.getincrementaldecoder("utf-8")()

    def reset(self):
        self._decoder = codecs.getincrementaldecoder("utf-8")()

    def flush(self) -> str:
        """Return any buffered partial character (final flush)."""
        tail = self._decoder.decode(b"", final=True)
        self.reset()
        return tail

    def decode_token(self, tokenizer, token_id) -> str:
        raw = tokenizer.get_token_bytes(int(token_id))
        if not raw:
            return ""
        try:
            return self._decoder.decode(raw)
        except UnicodeDecodeError:
            # Corrupt / unreadable sequence — fall back to a safe single-byte
            # decode and reset the incremental state so the stream stays sane.
            self.reset()
            return raw.decode("utf-8", errors="replace")





