# === Matrix Rain Canvas ===

class MatrixRain:
    """Animated Matrix-style falling code on a Canvas."""
    
    def __init__(self, canvas: tk.Canvas, width: int, height: int, max_items: int = 300):
        self.canvas = canvas
        self.canvas.configure(bg="#000000")  # Force black background
        self.width = width
        self.height = height
        self.columns = width // 16  # Character width spacing
        self.drops = [random.randint(-30, -1) for _ in range(self.columns)]
        self.speeds = [random.uniform(0.5, 1.5) for _ in range(self.columns)]
        self.chars_on_screen = []  # Track canvas item IDs
        self.running = True
        self.frame_count = 0
        self.max_items = max_items
        self.trail_length = max(3, height // 16)
    
    def update(self):
        """Update one frame of the matrix rain."""
        if not self.running:
            return
        
        self.frame_count += 1
        
        # Only update every 3rd frame for performance
        if self.frame_count % 2 != 0:
            return
        
        # Cleanup: remove old items (batch, O(n) not O(n^2))
        if self.frame_count % 15 == 0:
            cutoff = self.frame_count - 12
            keep = []
            for item_id, age in self.chars_on_screen:
                if age > cutoff:
                    keep.append((item_id, age))
                else:
                    try: self.canvas.delete(item_id)
                    except: pass
            self.chars_on_screen = keep
        
        # Hard cap: if too many items, nuke oldest
        if len(self.chars_on_screen) > self.max_items:
            excess = len(self.chars_on_screen) - self.max_items
            for item_id, _ in self.chars_on_screen[:excess]:
                try: self.canvas.delete(item_id)
                except: pass
            self.chars_on_screen = self.chars_on_screen[excess:]
        
        for i in range(self.columns):
            # Move drop down
            self.drops[i] += self.speeds[i]
            
            x = i * 16 + 8
            y = int(self.drops[i] * 16)
            
            if y > 0 and y < self.height:
                char = random.choice(MATRIX_CHARS)
                
                # Head character (leading edge — brightest)
                item = self.canvas.create_text(
                    x, y, text=char,
                    font=("Consolas", 12),
                    fill=COLORS["matrix_green"],
                    anchor=tk.CENTER
                )
                self.chars_on_screen.append((item, self.frame_count))
                
                # Trail character (fading behind)
                if y - 16 > 0 and random.random() < 0.7:
                    trail_char = random.choice(MATRIX_CHARS)
                    trail = self.canvas.create_text(
                        x, y - 16, text=trail_char,
                        font=("Consolas", 11),
                        fill=COLORS["matrix_dim"],
                        anchor=tk.CENTER
                    )
                    self.chars_on_screen.append((trail, self.frame_count))
                
                # Second trail (even dimmer, further up)
                if y - 32 > 0 and random.random() < 0.4:
                    trail2_char = random.choice(MATRIX_CHARS)
                    trail2 = self.canvas.create_text(
                        x, y - 32, text=trail2_char,
                        font=("Consolas", 10),
                        fill="#001a00",
                        anchor=tk.CENTER
                    )
                    self.chars_on_screen.append((trail2, self.frame_count))
            
            # Reset drop when it goes off screen
            if y > self.height + 50:
                self.drops[i] = random.randint(-20, -1)
                self.speeds[i] = random.uniform(0.5, 1.5)
    
    def stop(self):
        self.running = False


# === Blood Drip Title Animation ===

class BloodTitle:
    """Animated blood-drip title text."""
    
    def __init__(self, canvas: tk.Canvas, text: str, x: int, y: int):
        self.canvas = canvas
        self.text = text
        self.x = x
        self.y = y
        self.drips = []  # (x, y, speed, length)
        self.frame = 0
        self.title_id = None
        self.glow_ids = []
        
        # Create the main title
        self._create_title()
        
        # Initialize drip points along the text
        text_width = len(text) * 22
        for i in range(8):
            dx = x - text_width // 2 + random.randint(0, text_width)
            self.drips.append({
                "x": dx,
                "y": y + 15,
                "speed": random.uniform(0.5, 1.5),
                "length": random.randint(20, 60),
                "offset": random.randint(0, 100),
                "items": []
            })
    
    def _create_title(self):
        """Create the title with glow effect."""
        # Glow layers (behind)
        for offset in range(3, 0, -1):
            glow = self.canvas.create_text(
                self.x, self.y,
                text=self.text,
                font=("Impact", 32, "bold"),
                fill=COLORS["blood_red"],
                anchor=tk.CENTER
            )
            self.glow_ids.append(glow)
        
        # Main title
        self.title_id = self.canvas.create_text(
            self.x, self.y,
            text=self.text,
            font=("Impact", 32, "bold"),
            fill=COLORS["blood_bright"],
            anchor=tk.CENTER
        )
    
    def update(self):
        """Animate blood drips."""
        self.frame += 1
        
        # Pulsing glow on title
        pulse = abs(math.sin(self.frame * 0.05)) * 0.3 + 0.7
        # We can't easily change opacity in tkinter, so we alternate colors
        if self.frame % 10 == 0:
            colors = ["#8b0000", "#aa0000", "#cc0000", "#aa0000"]
            color = colors[(self.frame // 10) % len(colors)]
            for glow_id in self.glow_ids:
                try:
                    self.canvas.itemconfig(glow_id, fill=color)
                except:
                    pass
        
        # Animate drips
        for drip in self.drips:
            if (self.frame + drip["offset"]) % 60 == 0:
                # Start a new drip
                drip["y"] = self.y + 15
            
            if drip["y"] < self.y + 15 + drip["length"]:
                drip["y"] += drip["speed"]
                
                # Draw drip segment
                item = self.canvas.create_oval(
                    drip["x"] - 1, drip["y"] - 2,
                    drip["x"] + 1, drip["y"] + 2,
                    fill=COLORS["blood_drip"],
                    outline=""
                )
                drip["items"].append((item, self.frame))
            
            # Clean old drip items
            for item_id, age in drip["items"][:]:
                if self.frame - age > 40:
                    try:
                        self.canvas.delete(item_id)
                    except:
                        pass
                    drip["items"].remove((item_id, age))


