    def _toggle_file_browser(self):
        """Show/hide the file browser panel."""
        if self.file_browser_visible:
            self.file_browser_frame.pack_forget()
            self.file_browser_visible = False
        else:
            # Pack before the chat panel
            if hasattr(self, 'chat_panel'):
                self.file_browser_frame.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 5),
                                             before=self.chat_panel)
            else:
                self.file_browser_frame.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 5))
            self.file_browser_visible = True
            self._browse_path(self.path_var.get())
    
    def _browse_path(self, path: str):
        """Navigate to a directory and list its contents."""
        path = Path(path)
        if not path.exists() or not path.is_dir():
            return
        
        self.path_var.set(str(path))
        self.file_listbox.delete(0, tk.END)
        self.current_files.clear()
        
        try:
            entries = sorted(path.iterdir(), key=lambda p: (not p.is_dir(), p.name.lower()))
            
            for entry in entries:
                try:
                    is_dir = entry.is_dir()
                    size = entry.stat().st_size if not is_dir else 0
                    size_str = self._format_size(size) if not is_dir else ""
                    ext = entry.suffix.lower()
                    
                    file_entry = FileEntry(
                        name=entry.name, path=str(entry),
                        is_dir=is_dir, size=size,
                        size_str=size_str, extension=ext
                    )
                    self.current_files.append(file_entry)
                    
                    # Display with icons
                    # Display with icons
                    is_model = ext in (".gguf", ".ntmre", ".safetensors", ".onnx", ".bin")
                    if is_dir:
                        display = f"📁 {entry.name}"
                    elif is_model:
                        display = f"🧠 {entry.name}  ({size_str})"
                    else:
                        display = f"   {entry.name}  ({size_str})"
                    
                    self.file_listbox.insert(tk.END, display)
                    
                    # Color Model files green
                    if is_model:
                        idx = self.file_listbox.size() - 1
                        self.file_listbox.itemconfig(idx, fg=COLORS["matrix_green"])
                    elif is_dir:
                        idx = self.file_listbox.size() - 1
                        self.file_listbox.itemconfig(idx, fg=COLORS["warning"])
                        
                except PermissionError:
                    pass
                    
        except PermissionError:
            self.file_listbox.insert(tk.END, "⚠️ Permission denied")
    
    def _on_file_double_click(self, event):
        """Handle double-click on a file/folder."""
        selection = self.file_listbox.curselection()
        if not selection:
            return
        
        idx = selection[0]
        if idx >= len(self.current_files):
            return
        
        entry = self.current_files[idx]
        
        if entry.is_dir:
            self._browse_path(entry.path)
        elif entry.extension in (".gguf", ".ntmre", ".safetensors", ".onnx", ".bin"):
            self._load_model(entry.path)
    
    def _on_file_select(self, event):
        """Handle file selection — update info and enable load button."""
        selection = self.file_listbox.curselection()
        if not selection:
            self.file_info_label.config(text="")
            self.load_selected_btn.config(state=tk.DISABLED)
            return
        
        idx = selection[0]
        if idx >= len(self.current_files):
            return
        
        entry = self.current_files[idx]
        
        if entry.is_dir:
            self.file_info_label.config(text=f"Folder: {entry.name}")
            self.load_selected_btn.config(state=tk.DISABLED)
        elif entry.extension in (".gguf", ".ntmre", ".safetensors", ".onnx", ".bin"):
            self.file_info_label.config(text=f"Model: {entry.name}\nSize: {entry.size_str}")
            self.load_selected_btn.config(state=tk.NORMAL)
        else:
            self.file_info_label.config(text=f"File: {entry.name}\nSize: {entry.size_str}")
            self.load_selected_btn.config(state=tk.DISABLED)
    
    def _load_selected_file(self):
        """Load the currently selected model file."""
        selection = self.file_listbox.curselection()
        if not selection:
            return
        
        idx = selection[0]
        if idx >= len(self.current_files):
            return
        
        entry = self.current_files[idx]
        if entry.extension in (".gguf", ".ntmre", ".safetensors", ".onnx", ".bin"):
            self._load_model(entry.path)
    
    def _browse_parent(self):
        """Navigate to parent directory."""
        current = Path(self.path_var.get())
        parent = current.parent
        if parent != current:
            self._browse_path(str(parent))
    
    def _browse_home(self):
        """Navigate to home directory."""
        self._browse_path(str(Path.home()))
    
    def _browse_models_dir(self):
        """Navigate to the models download directory."""
        self._browse_path(str(self.download_manager.download_dir))
    
    def _refresh_browser(self):
        """Refresh the current directory listing."""
        self._browse_path(self.path_var.get())
    
    @staticmethod
    def _format_size(size_bytes: int) -> str:
        """Format file size to human-readable string."""
        if size_bytes == 0:
            return "0 B"
        units = ["B", "KB", "MB", "GB", "TB"]
        i = 0
        size = float(size_bytes)
        while size >= 1024 and i < len(units) - 1:
            size /= 1024
            i += 1
        return f"{size:.1f} {units[i]}"
    
