        self.matrix_rain = MatrixRain(self.title_canvas, _cw, 80)
        
        def _on_matrix_resize(event):
            self.matrix_rain.width = event.width
            self.matrix_rain.height = event.height
            new_cols = event.width // 16
            while len(self.matrix_rain.drops) < new_cols:
                self.matrix_rain.drops.append(random.randint(-20, -1))
                self.matrix_rain.speeds.append(random.uniform(0.5, 1.5))
            self.matrix_rain.columns = new_cols
        self.title_canvas.bind("<Configure>", _on_matrix_resize)
        
