    def _section_header(self, parent, text: str):
        """Create a section header in the sidebar."""
        lbl = tk.Label(parent, text=text,
                bg=COLORS["bg_panel"], fg=COLORS["blood_bright"],
                font=("Impact", 11), anchor=tk.W).pack(fill=tk.X, padx=8, pady=(10, 2))
        
        # Separator line
        sep = tk.Frame(parent, height=1, bg=COLORS["blood_red"])
        sep.pack(fill=tk.X, padx=8, pady=(0, 4))
    
    def _collapsible_section(self, parent, text: str, section_id: str,
                             collapsed=True, premium=False, tier=0, tier_desc=""):
        """Create a collapsible section. Hidden entirely if tier-locked."""
        self._collapsed_sections[section_id] = collapsed

        # --- Locked: hide entirely (tier info is on the pricing page only) ---
        if tier > 0 and self._unlocked_tier < tier:
            dummy = tk.Frame(parent, bg=COLORS["bg_panel"])
            self._collapsible_frames[section_id] = {
                "frame": dummy, "arrow": None, "tier": tier,
                "lock_lbl": None, "parent": parent, "sep": None,
                "wrapper": dummy, "locked": True,
            }
            return dummy

        # --- Unlocked: build the full section ---
        wrapper_frame = tk.Frame(parent, bg=COLORS["bg_panel"])
        wrapper_frame.pack(fill=tk.X)

        header_frame = tk.Frame(wrapper_frame, bg=COLORS["bg_panel"], cursor="hand2")
        header_frame.pack(fill=tk.X, padx=4, pady=(8, 0))

        arrow_text = "\u25b6" if collapsed else "\u25bc"
        arrow_lbl = tk.Label(header_frame, text=arrow_text,
                bg=COLORS["bg_panel"], fg=COLORS["blood_bright"], font=("Consolas", 10))
        arrow_lbl.pack(side=tk.LEFT, padx=(4, 2))

        title_lbl = tk.Label(header_frame, text=text,
                bg=COLORS["bg_panel"], fg=COLORS["blood_bright"],
                font=("Impact", 11), anchor=tk.W)
        title_lbl.pack(side=tk.LEFT, padx=(0, 4))

        if tier > 0 and self._unlocked_tier >= tier:
            tier_colors = {1: COLORS["matrix_green"], 2: COLORS["warning"], 3: COLORS["gold"], 4: COLORS["blood_bright"]}
            tk.Label(header_frame, text=f"T{tier}",
                    bg=COLORS["bg_panel"], fg=tier_colors.get(tier, COLORS["text_dim"]),
                    font=("Consolas", 8, "bold")).pack(side=tk.RIGHT, padx=(0, 2))

        sep = tk.Frame(wrapper_frame, height=1, bg=COLORS["blood_red"])
        sep.pack(fill=tk.X, padx=8, pady=(2, 0))

        content_frame = tk.Frame(wrapper_frame, bg=COLORS["bg_panel"])
        if not collapsed:
            content_frame.pack(fill=tk.X, padx=0, pady=(2, 0))

        self._collapsible_frames[section_id] = {
            "frame": content_frame, "arrow": arrow_lbl, "tier": tier,
            "lock_lbl": None, "parent": parent, "sep": sep, "wrapper": wrapper_frame,
        }

        def on_click(event, sid=section_id):
            self._toggle_section(sid)
        header_frame.bind("<Button-1>", on_click)
        arrow_lbl.bind("<Button-1>", on_click)
        title_lbl.bind("<Button-1>", on_click)

        return content_frame
    def _toggle_section(self, section_id: str):
        """Toggle a collapsible section open/closed."""
        info = self._collapsible_frames.get(section_id)
        if not info:
            return
        collapsed = self._collapsed_sections[section_id]
        if collapsed:
            info["frame"].pack(fill=tk.X, padx=0, pady=(2, 0), after=info["sep"])
            info["arrow"].config(text="\u25bc")
            self._collapsed_sections[section_id] = False
        else:
            info["frame"].pack_forget()
            info["arrow"].config(text="\u25b6")
            self._collapsed_sections[section_id] = True
