    def _validate_license_key(self, key: str):
        """Validate license key, protected by Nightmare Security. Returns tier (1-4) or None."""
        import hashlib
        from pathlib import Path
        self._last_valid_key = key  # Track for persistent unlock

        # ── Ed25519 signed licenses (new asymmetric format: ND-...) ──────
        # The app holds only the PUBLIC key; licenses are signed offline
        # with the developer's private key (see core_mind/license_keygen.py).
        # T3/T4 are HWID node-locked; T1/T2 are floating.  Unforgeable
        # without the private key, which never ships in the software.
        try:
            from core_mind.license_crypto import validate_license as _ed_validate
            tier = _ed_validate(key)
            if tier is not None:
                return tier
        except Exception:
            pass

        # Master override (hash-only — plaintext never stored in source)
        _NM_HASH = "7a180f235d7a44a2106cb4dc7d18845944ff1324600b9be844dfc48752210a8d"
        _ADMIN_HASHES = {
            _NM_HASH,
            "2aab0a6939200a432069dfb5d57c0d80dac2815419e8d23753bb5936b3b9b26d",
            "56e64c2dee86cd7402eccdc24f223bed724a66992a32ea64160c9ec046678d76",  # John G
        }
        _key_sha = hashlib.sha256(key.encode()).hexdigest()
        if _key_sha in _ADMIN_HASHES or key in ("cccccdgdgkghlitledjicekejknguikieflddhfvhknj", "cccccdgdgkghbkbfrlkfnirgcjeeuctnrdhgkdiunjvv"):
            admin_file = Path(__file__).parent / "nightmare_suite" / ".admin"
            if _key_sha == _NM_HASH and admin_file.exists():
                admin_file.unlink()
            return 4

        # ── One-time online licence activation (ntmre.com/activate) ─────
        # Master override above bypasses this on purpose: Caleb's own
        # unlock must work offline. For all other keys:
        #  1) a valid offline activation file for this key/HWID unlocks, no network;
        #  2) otherwise try one online activation (Worker verifies the key
        #     against Suite formats + its internal list, marks it used,
        #     binds it to this HWID, returns an activation token);
        #  3) if the Worker says already-used / invalid / tier mismatch,
        #     do NOT fall back to local validation — that is the pass-around block;
        #  4) if the Worker endpoint is simply unreachable (not yet deployed,
        #     DNS, timeout, 404), fall through to local validation below, so
        #     keys still work before the Worker is live. Once the Worker is
        #     live, case 3 is what enforces one-machine activation.
        try:
            from nightmare_activation import verify_offline_activation, activate_once
            _off_tier = verify_offline_activation(key)
            if _off_tier is not None:
                return _off_tier
            try:
                _act_tier, _act = activate_once(key)
                return _act_tier
            except ValueError:
                # Worker rejected the key (already used, invalid, mismatch):
                # do not fall back to local-only validation.
                return None
            except Exception:
                # Network / endpoint unreachable: fall through to local validation.
                pass
        except Exception:
            # Activation module missing/unavailable: fall through to local validation.
            pass
        
        # protected by Nightmare Security validation
        try:
            from core_mind.ghostrider_shield import verify_license_key, verify_password
            
            # Check against stored sealed keys
            sealed_keys_file = Path(__file__).parent / "nightmare_suite" / ".keys"
            if sealed_keys_file.exists():
                for line in sealed_keys_file.read_text().strip().split('\n'):
                    if '|' in line:
                        tier_str, stored_hash = line.split('|', 1)
                        if verify_license_key(key, stored_hash.strip()):
                            return int(tier_str.strip())
            
            # Check as admin password (GR sealed)
            admin_file = Path(__file__).parent / "nightmare_suite" / ".admin"
            if admin_file.exists():
                stored = admin_file.read_text().strip()
                if verify_password(key, stored):
                    return 3
        except ImportError:
            pass
        
        # Fallback: checksum-based format validation (works without gr_hash compiled)
        # Uses SHA-256-derived checksum so random strings don't pass
        try:
            from core_mind.ghostrider_shield import validate_key_format
            fmt_tier = validate_key_format(key)
            if fmt_tier is not None:
                return fmt_tier
        except ImportError:
            pass
        
        # Legacy SHA-256 admin password check
        admin_file = Path(__file__).parent / "nightmare_suite" / ".admin"
        if admin_file.exists():
            stored = admin_file.read_text().strip()
            if hashlib.sha256(key.encode()).hexdigest() == stored:
                return 3
        return None
    
    def _on_persona_change(self, selected_name):
        """Handle persona dropdown change."""
        if self.persona_manager.set_active(selected_name):
            persona = self.persona_manager.get_active()
            
            # Update description label
            self.persona_desc_label.config(text=persona.description)
            
            # Update parameter sliders with persona defaults
            self.temperature.set(persona.temperature)
            self.top_p.set(persona.top_p)
            self.top_k.set(persona.top_k)
            if hasattr(persona, 'repeat_penalty'):
                self.repeat_penalty.set(persona.repeat_penalty)
            if hasattr(persona, 'max_tokens'):
                self.max_tokens.set(persona.max_tokens)
            
            # Show greeting in chat
            if persona.greeting:
                self._append_ai_greeting(persona.greeting)
    
    def _append_ai_greeting(self, text: str):
        """Show a persona greeting in chat (not saved to session)."""
        self.chat_display.config(state=tk.NORMAL)
        self.chat_display.insert(tk.END, f"🎭 {self.persona_manager.get_active().name}: ", "ai_name")
        self.chat_display.insert(tk.END, text + "\n\n", "ai_text")
        self._trim_chat_display()
        self.chat_display.config(state=tk.DISABLED)
        self.chat_display.see(tk.END)

    def _refresh_persona_dropdown(self):
        """Rebuild the persona dropdown with current persona list."""
        if not hasattr(self, 'persona_dropdown'):
            return
        names = [p.name for p in self.persona_manager.list_all()]
        if not names:
            names = ["None"]
        menu = self.persona_dropdown["menu"]
        menu.delete(0, tk.END)
        for n in names:
            menu.add_command(label=n, command=lambda val=n: (self.active_persona_name.set(val), self._on_persona_change(val)))

