    def _get_windows_voices(self):
        """Return installed Windows System.Speech voice names."""
        voices = ["Default"]
        if os.name != "nt":
            return voices
        try:
            result = subprocess.run(
                ["powershell", "-NoProfile", "-NonInteractive", "-Command",
                 "Add-Type -AssemblyName System.Speech; "
                 "(New-Object System.Speech.Synthesis.SpeechSynthesizer).GetInstalledVoices() | "
                 "ForEach-Object { $_.VoiceInfo.Name }"],
                capture_output=True, text=True, timeout=15,
                startupinfo=self._hidden_process_startupinfo(),
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            if result.returncode == 0:
                voices.extend(line.strip() for line in result.stdout.splitlines()
                              if line.strip() and line.strip() not in voices)
        except Exception:
            pass
        return voices

    @staticmethod
    def _hidden_process_startupinfo():
        if os.name != "nt":
            return None
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        startupinfo.wShowWindow = subprocess.SW_HIDE
        return startupinfo

    def _speak_text(self, text):
        """Speak through the installed Windows voice used by Narrator."""
        try:
            script = (
                "Add-Type -AssemblyName System.Speech; "
                "$s = New-Object System.Speech.Synthesis.SpeechSynthesizer; "
                "$voice = $env:NIGHTMARE_TTS_VOICE; "
                "if ($voice) { try { $s.SelectVoice($voice) } catch {} }; "
                "$inputText = [Console]::In.ReadToEnd(); "
                "$s.Speak($inputText); $s.Dispose();"
            )
            startupinfo = None
            creationflags = 0
            if os.name == "nt":
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                startupinfo.wShowWindow = subprocess.SW_HIDE
                creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            selected_voice = self.tts_voice.get() if hasattr(self, "tts_voice") else "Default"
            speech_env = os.environ.copy()
            if selected_voice and selected_voice != "Default":
                speech_env["NIGHTMARE_TTS_VOICE"] = selected_voice
            else:
                speech_env.pop("NIGHTMARE_TTS_VOICE", None)
            result = subprocess.run(
                ["powershell", "-NoProfile", "-NonInteractive",
                 "-ExecutionPolicy", "Bypass", "-Command", script],
                input=str(text), text=True, capture_output=True,
                # Must be explicit. With text=True and no encoding, Python
                # encodes stdin with the ANSI codepage (cp1252 here), which
                # cannot represent her emoji -- an emoji in her reply raised
                # UnicodeEncodeError inside the writer thread and silently
                # killed the speech call. utf-8 is what PowerShell reads.
                encoding="utf-8", errors="replace",
                timeout=120, startupinfo=startupinfo, creationflags=creationflags,
                env=speech_env)
            if result.returncode != 0:
                raise RuntimeError(result.stderr.strip() or f"PowerShell exited {result.returncode}")
        except Exception as exc:
            self.output_queue.put(("system", f"⚠️ Windows Narrator voice unavailable: {exc}\n"))

