    def _apply_sampler_preset(self, preset):
        presets = {
            "Balanced": (0.7, 40, 0.9, 0.05, 0.0, 1.05, 0.0),
            "Coder": (0.25, 20, 0.85, 0.03, 0.0, 1.02, 0.2),
            "Writer": (0.95, 60, 0.96, 0.02, 0.0, 1.08, 0.0),
            "Analyst": (0.35, 30, 0.88, 0.04, 0.0, 1.1, 0.1),
            "Heretic": (1.1, 80, 0.98, 0.01, 0.02, 1.02, 0.0),
        }
        values = presets.get(str(preset), presets["Balanced"])
        for variable, value in zip((self.temperature, self.top_k, self.top_p, self.min_p,
                                    self.top_a, self.repeat_penalty, self.dry_multiplier), values):
            variable.set(value)

    def _update_context_preview(self, value=None):
        tokens = int(self.context_length.get())
        model_dim = int(getattr(getattr(self, "model", None), "dim", 4096))
        layers = int(getattr(getattr(self, "model", None), "n_layers", 32))
        estimated_gb = tokens * model_dim * layers * 2 * 2 / (1024 ** 3)
        if hasattr(self, "context_vram_label"):
            self.context_vram_label.config(
                text=f"{tokens:,} tokens | KV estimate: {estimated_gb:.2f} GB VRAM")

    # =================================================================
    # Attachments: files dropped or pasted into the chat
    #
    # Three ways in, because there are three things a person actually does:
    #   - Ctrl+V with files copied in Explorer  (grabclipboard -> [paths])
    #   - Ctrl+V with an image copied from a screen snip or browser
    #   - the Attach button, which allows multi-select
    #
    # Deliberately NOT OS drag-and-drop. That needs tkinterdnd2, which is not
    # installed, and silently pulling in a package to satisfy one widget is
    # not a thing to do without asking. Paste and the button cover the same
    # ground with what is already here (PIL handles the clipboard).
    #
    # Attachments accumulate in self.attachments and are injected into the
    # prompt by _format_attachments(), the same way attached_context is.
    # =================================================================

    ATTACH_MAX_TEXT = 12000        # chars of text per attachment
    ATTACH_MAX_FILES = 8           # per turn

    def _ensure_attachment_state(self):
        if not hasattr(self, "attachments"):
            self.attachments = []          # list of dicts
        return self.attachments

    def _attach_files(self, paths):
        """Attach a list of file paths. Reads text; describes images."""
        paths = [p for p in (paths or []) if p and os.path.isfile(p)]
        if not paths:
            return 0
        atts = self._ensure_attachment_state()
        added = 0
        for p in paths:
            if len(atts) >= self.ATTACH_MAX_FILES:
                self._append_system(
                    "\u26A0\uFE0F Attachment limit (%d) reached.\n"
                    % self.ATTACH_MAX_FILES)
                break
            try:
                att = self._read_attachment(p)
            except Exception as exc:
                self._append_system("\u26A0\uFE0F Could not attach %s: %s\n"
                                    % (os.path.basename(p), exc))
                continue
            if att is None:
                continue
            atts.append(att)
            added += 1
            kind = att.get("kind", "?")
            extra = ""
            if kind == "image":
                extra = " (%dx%d)" % att.get("size", (0, 0))
            elif att.get("chars"):
                extra = " (%s chars)" % format(att["chars"], ",")
            self._append_system("\U0001F4CE Attached %s: %s%s\n"
                                % (kind, att["name"], extra))
        if added:
            self._refresh_attachment_bar()
        return added

    def _read_attachment(self, path):
        """Turn one file into an attachment record, or None if unusable.

        Images are recorded with their pixel size and mean colour rather than
        being decoded to text -- a vision model could use the path later, but
        claiming to "read" an image as text would be a lie. The description
        gives the model enough to acknowledge it accurately.
        """
        name = os.path.basename(path)
        ext = os.path.splitext(path)[1].lower()
        img_exts = (".png", ".jpg", ".jpeg", ".bmp", ".gif", ".webp", ".tif",
                    ".tiff")

        if ext in img_exts:
            try:
                from PIL import Image
                with Image.open(path) as im:
                    w, h = im.size
                    mode = im.mode
                    thumb = im.convert("RGB").resize((8, 8))
                    px = list(thumb.getdata())
                    avg = tuple(int(sum(c[i] for c in px) / len(px))
                                for i in range(3))
                return {
                    "kind": "image",
                    "name": name,
                    "path": path,
                    "size": (w, h),
                    "mode": mode,
                    "avg_rgb": avg,
                    "chars": 0,
                }
            except Exception:
                # PIL could not read it; fall through and try it as text so a
                # mislabelled file is not silently dropped.
                pass

        if ext == ".pdf":
            try:
                import pypdf
                text = "\n".join(page.extract_text() or ""
                                 for page in pypdf.PdfReader(path).pages)
            except Exception as exc:
                raise RuntimeError("PDF read failed: %s" % exc)
        elif ext == ".docx":
            try:
                from docx import Document
                text = "\n".join(p.text for p in Document(path).paragraphs)
            except Exception as exc:
                raise RuntimeError("DOCX read failed: %s" % exc)
        else:
            if os.path.getsize(path) > 4 * 1024 * 1024:
                raise RuntimeError("file too large to inline (>4 MB)")
            text = Path(path).read_text(encoding="utf-8", errors="replace")

        text = text.strip()
        if not text:
            return None
        return {
            "kind": "text",
            "name": name,
            "path": path,
            "text": text[:self.ATTACH_MAX_TEXT],
            "chars": len(text),
        }

    def _on_paste(self, event=None):
        """Ctrl+V handler: files copied in Explorer, or an image.

        Returns "break" only when something was attached, so an ordinary text
        paste still reaches the Text widget untouched.
        """
        try:
            from PIL import ImageGrab
        except Exception:
            return None
        try:
            data = ImageGrab.grabclipboard()
        except Exception:
            return None
        if not data:
            return None

        # Files copied in Explorer arrive as a list of paths.
        if isinstance(data, list):
            n = self._attach_files([str(p) for p in data])
            return "break" if n else None

        # An image on the clipboard: save it so the path exists for later use.
        try:
            att_dir = Path(getattr(self, "save_dir", Path.cwd())) / "attachments"
            att_dir.mkdir(parents=True, exist_ok=True)
            fn = att_dir / ("paste_%d.png" % int(time.time()))
            data.save(str(fn))
            n = self._attach_files([str(fn)])
            return "break" if n else None
        except Exception:
            return None

    def _attach_dialog(self):
        """Multi-select attach from the file picker."""
        paths = filedialog.askopenfilenames(
            title="Attach files",
            filetypes=[("All supported",
                        "*.txt *.md *.py *.json *.csv *.log *.pdf *.docx "
                        "*.png *.jpg *.jpeg *.bmp *.gif *.webp"),
                       ("Text", "*.txt *.md *.py *.json *.csv *.log"),
                       ("Images", "*.png *.jpg *.jpeg *.bmp *.gif *.webp"),
                       ("All files", "*.*")])
        if paths:
            self._attach_files(list(paths))

    def _clear_attachments(self):
        self._ensure_attachment_state().clear()
        self._refresh_attachment_bar()
        self._append_system("\U0001F5D1\uFE0F Attachments cleared.\n")

    def _refresh_attachment_bar(self):
        """Redraw the chip row above the input box."""
        bar = getattr(self, "_attach_bar", None)
        if bar is None:
            return
        for w in bar.winfo_children():
            w.destroy()
        atts = self._ensure_attachment_state()
        if not atts:
            bar.pack_forget()
            return
        bar.pack(fill=tk.X, side=tk.BOTTOM)
        tk.Label(bar, text="\U0001F4CE", bg=COLORS["bg_card"],
                 fg=COLORS["matrix_green"], font=("Consolas", 10)
                 ).pack(side=tk.LEFT, padx=(6, 2))
        for i, a in enumerate(atts):
            icon = "\U0001F5BC\uFE0F" if a.get("kind") == "image" else "\U0001F4C4"
            label = "%s %s" % (icon, a["name"][:22])
            tk.Label(bar, text=label, bg=COLORS["bg_panel"],
                     fg=COLORS["text"], font=("Consolas", 9),
                     padx=6, pady=1).pack(side=tk.LEFT, padx=2)
        tk.Button(bar, text="\u2715 clear", command=self._clear_attachments,
                  bg=COLORS["bg_card"], fg=COLORS["blood_bright"],
                  font=("Consolas", 9), relief=tk.FLAT, cursor="hand2"
                  ).pack(side=tk.RIGHT, padx=6)

    def _format_attachments(self, atts=None):
        """Render attachments into prompt text. Empty string if none."""
        if atts is None:
            atts = getattr(self, "attachments", None)
        if not atts:
            return ""
        parts = ["\n\n[ATTACHMENTS]"]
        for a in atts:
            if a.get("kind") == "image":
                w, h = a.get("size", (0, 0))
                parts.append(
                    "[IMAGE] %s (%dx%d, %s) at %s -- the user attached this "
                    "image; you can see that it exists and its dimensions, "
                    "but not its contents unless a vision model is loaded."
                    % (a["name"], w, h, a.get("mode", "?"), a.get("path", "")))
            else:
                parts.append("[FILE] %s\n%s" % (a["name"],
                                                a.get("text", "")))
        parts.append("[/ATTACHMENTS]")
        return "\n".join(parts)

    def _attach_context_document(self):
        path = filedialog.askopenfilename(
            title="Attach document context",
            filetypes=[("Documents", "*.txt *.md *.py *.json *.csv *.pdf *.docx"),
                       ("All files", "*.*")])
        if not path:
            return
        try:
            suffix = Path(path).suffix.lower()
            if suffix == ".pdf":
                import pypdf
                text = "\n".join(page.extract_text() or "" for page in pypdf.PdfReader(path).pages)
            elif suffix == ".docx":
                from docx import Document
                text = "\n".join(paragraph.text for paragraph in Document(path).paragraphs)
            else:
                text = Path(path).read_text(encoding="utf-8", errors="replace")
            self.attached_context = text[:12000]
            self.attached_context_name = Path(path).name
            self._append_system(f"📎 Attached context: {self.attached_context_name}\n")
        except Exception as exc:
            messagebox.showerror("Attach context", f"Could not read document: {exc}")
    
    # === Animation Loop ===
    
    def _trim_chat_display(self, max_lines: int = 5000):
        """Trim chat display to prevent unbounded memory growth."""
        try:
            line_count = int(self.chat_display.index('end-1c').split('.')[0])
            if line_count > max_lines:
                # Delete oldest 1000 lines
                self.chat_display.config(state="normal")
                self.chat_display.delete("1.0", f"{line_count - max_lines + 1000}.0")
                self.chat_display.config(state="disabled")
        except:
            pass
    
    def _toggle_sidebar(self):
        """Slide the right panel in/out."""
        if self._sidebar_visible:
            self._sidebar_frame.pack_forget()
            self._sidebar_toggle.config(text="▶")
            self._sidebar_visible = False
        else:
            self._sidebar_frame.pack(side=tk.RIGHT, fill=tk.Y)
            self._sidebar_toggle.config(text="◀")
            self._sidebar_visible = True

    def _toggle_verbose(self):
        """Toggle verbose debug output on/off across all modules."""
        import transformer
        import sampler as sampler_mod
        import tokenizer as tokenizer_mod
        
        enabled = self.verbose_var.get()
        transformer._NIGHTMARE_DEBUG = enabled
        sampler_mod._NIGHTMARE_DEBUG = enabled
        tokenizer_mod._NIGHTMARE_DEBUG = enabled
        os.environ["NIGHTMARE_DEBUG"] = "1" if enabled else "0"
        
        status = "ON" if enabled else "OFF"
        print(f"[Nightmare] Verbose output: {status}")
    
    def _strip_turn_scaffold(self, text: str) -> str:
        """
        Remove Gemma 4 turn/channel markers from a reply before it is shown.

        Gemma 4 emits <|turn>, <|channel> and <channel|> as real tokens. The
        local tensor loop strips stop strings but not these, so they surface
        verbatim in the chat window and a reply looks like a debug dump.

        Dream text already goes through the same cleanup in
        dream binder; this is the chat-side half of that, kept here
        rather than imported so the suite has no import-order dependency on
        the dream binder just to render a reply.

        Deliberately does NOT stop generation at <turn|>: the model's reply
        is already complete by the time this runs, and <turn|> has the
        highest logit on most prompts, so treating it as a stop condition is
        what produces empty replies. This only tidies what arrived.
        """
        if not text:
            return ""
        t = str(text)
        try:
            import re as _re
            # Channel header plus its close, whether or not there is content.
            t = _re.sub(r"<\|channel>[a-zA-Z_]*\s*<channel\|>", "", t)
            # A close with no matching header. The header can arrive split
            # across tokens, so the leading "<|chan" may be truncated to
            # "|channel>" -- which is why this pattern also matches a bare
            # pipe and would otherwise survive every pass.
            t = _re.sub(r"<\|channel>[a-zA-Z_]*\n?", "", t)
            t = _re.sub(r"(?:<\||\|)channel>[a-zA-Z_]*\s*", "", t)
            t = _re.sub(r"<channel\|>", "", t)
            t = _re.sub(r"^\s*turn\s*\n", "", t)
            # "...thought" with no newline before it: the header split
            # across tokens leaves the word glued to the front of the reply.
            t = _re.sub(r"^\s*thought\s*\n?", "", t)
            # Turn header / footer.
            t = _re.sub(r"<\|turn>[a-zA-Z_]*\s*", "", t)
            t = _re.sub(r"<turn\|>", "", t)
            t = t.strip()
        except Exception:
            return text
        return t if t.strip() else str(text).strip()

    def _tick_speed_counter(self, gen_start: float, prefill_time: float = 0.0):
        """
        Forward the live counters to the display, throttled.

        Called from inside the generation loop on every token. Pushing to
        tkinter that often starves the loop it is measuring, so updates at
        most a few times a second. The final value is always sent so the
        panel does not freeze on a stale number when generation stops.
        """
        now = time.time()
        last = getattr(self, "_speed_tick_last", 0.0)
        if now - last < 0.25:
            return
        self._speed_tick_last = now

        elapsed = now - gen_start
        if elapsed <= 0:
            return
        gen_tps = self._gen_tokens / elapsed
        prefill_tps = 0.0
        if prefill_time and prefill_time > 0:
            # _gen_tokens is generation only; prefill counted separately.
            try:
                prefill_tps = float(getattr(self, "_prefill_tokens", 0)
                                    ) / float(prefill_time)
            except Exception:
                prefill_tps = 0.0

        try:
            self.root.after(0, lambda: self._update_speed_counter(
                gen_tps, prefill_tps, 0.0, int(self._gen_tokens or 0)))
        except Exception:
            pass

    def _update_speed_counter(self, tok_per_sec: float, prefill_tps: float = 0,
                               ttft_ms: float = 0, total_tokens: int = 0):
        """Update the live speed counter display."""
        try:
            self.speed_display.config(text=f"⚡ {tok_per_sec:.2f} tok/s")
            
            # Color based on speed
            if tok_per_sec >= 10:
                color = COLORS["matrix_green"]
            elif tok_per_sec >= 3:
                color = COLORS["warning"] if "warning" in COLORS else "#ffaa00"
            else:
                color = COLORS["blood_bright"]
            self.speed_display.config(fg=color)
            
            detail = f"Prefill: {prefill_tps:.1f} | Gen: {tok_per_sec:.2f} | TTFT: {ttft_ms:.0f}ms"
            if total_tokens > 0:
                detail += f" | Total: {total_tokens} tok"
            self.speed_detail.config(text=detail)
        except tk.TclError:
            pass  # Widget destroyed
    
    # === MATRIX RAIN CONTROLS ===
    
    _MATRIX_COLORS = {
        "Green": ("#00ff41", "#003b00"),
        "Red": ("#ff0000", "#3b0000"),
        "Blue": ("#0088ff", "#001a3b"),
        "Purple": ("#bb86fc", "#1a0033"),
        "Gold": ("#ffd700", "#3b2e00"),
        "Cyan": ("#00ffff", "#003b3b"),
        "White": ("#ffffff", "#333333"),
    }
    
    def _update_matrix_color(self, color_name):
        """Change matrix rain color across all canvases."""
        if color_name in self._MATRIX_COLORS:
            bright, dim = self._MATRIX_COLORS[color_name]
            # Update the global color references used by MatrixRain
            COLORS["matrix_green"] = bright
            COLORS["matrix_dim"] = dim
            COLORS["matrix_bright"] = bright
    
    def _update_matrix_speed(self, val):
        """Change matrix animation speed (ms between frames)."""
        speed = int(val)
        # Cancel current animation and restart with new speed
        if self._animate_id:
            self.root.after_cancel(self._animate_id)
        self._animation_speed = speed
        self._animate()
    
    def _update_matrix_density(self, val):
        """Change how many columns are dropping."""
        density_pct = int(val)
        # Adjust columns active in each rain instance
        for rain in [self.matrix_rain]:
            if hasattr(rain, 'columns'):
                target = max(1, int(rain.columns * density_pct / 100))
                # Reset drop positions to activate/deactivate columns
                for i in range(len(rain.drops)):
                    if i < target:
                        if rain.drops[i] < -100:  # reactivate dormant
                            rain.drops[i] = random.randint(-10, -1)
                    else:
                        rain.drops[i] = -9999  # deactivate
        if hasattr(self, 'left_matrix_rain'):
            self.left_matrix_rain.columns = max(1, int(3 * int(val) / 100))
        if hasattr(self, 'right_matrix_rain'):
            self.right_matrix_rain.columns = max(1, int(3 * int(val) / 100))

    def _animate(self):
        """Main animation loop for Matrix rain + blood drips."""
        if not self._running:
            return
        self.matrix_rain.update()
        if hasattr(self, 'blood_title'):
            self.blood_title.update()
        # Side matrix rain strips
        if hasattr(self, 'left_matrix_rain'):
            self.left_matrix_rain.update()
        if hasattr(self, 'right_matrix_rain'):
            self.right_matrix_rain.update()
        speed = getattr(self, "_animation_speed", 50)
        self._animate_id = self.root.after(speed, self._animate)
    
    # === Chat Tab Management ===
    
    def _switch_tab(self, idx: int):
        """Switch to a different chat tab."""
        self.active_tab = idx
        self._refresh_tabs()
        self._reload_chat_display()
    
    def _new_tab(self):
        """Create a new chat tab."""
        n = len(self.chat_sessions) + 1
        self.chat_sessions.append(ChatSession(name=f"Chat {n}"))
        self.active_tab = len(self.chat_sessions) - 1
        self._refresh_tabs()
        self._reload_chat_display()
    
    def _tab_context_menu(self, event, idx):
        """Right-click menu for tabs."""
        menu = tk.Menu(self.root, tearoff=0, bg=COLORS["bg_card"],
                      fg=COLORS["text"], font=("Consolas", 11))
        menu.add_command(label="✏️ Rename", command=lambda: self._rename_tab(idx))
        menu.add_command(label="🗑️ Close", command=lambda: self._close_tab(idx))
        menu.post(event.x_root, event.y_root)
    
    def _rename_tab(self, idx):
        """Rename a chat tab."""
        name = simpledialog.askstring("Rename", "New name:",
                                      initialvalue=self.chat_sessions[idx].name,
                                      parent=self.root)
        if name:
            self.chat_sessions[idx].name = name
            self._refresh_tabs()
    
    def _close_tab(self, idx):
        """Close a chat tab."""
        if len(self.chat_sessions) <= 1:
            return  # Keep at least one tab
        
        self.chat_sessions.pop(idx)
        if self.active_tab >= len(self.chat_sessions):
            self.active_tab = len(self.chat_sessions) - 1
        self._refresh_tabs()
        self._reload_chat_display()
    
    def _reload_chat_display(self):
        """Reload the chat display for the active tab."""
        self.chat_display.config(state=tk.NORMAL)
        self.chat_display.delete("1.0", tk.END)
        
        session = self.chat_sessions[self.active_tab]
        for msg in session.messages:
            if msg.role == "user":
                self.chat_display.insert(tk.END, "You: ", "user_name")
                self.chat_display.insert(tk.END, msg.content + "\n", "user_text")
            elif msg.role == "ai":
                self.chat_display.insert(tk.END, "AI: ", "ai_name")
                self._md_render(self.chat_display, msg.content + "\n")
            elif msg.role == "system":
                self.chat_display.insert(tk.END, msg.content + "\n", "system")
        
        self.chat_display.config(state=tk.DISABLED)
        self.chat_display.see(tk.END)

    @staticmethod
    def _md_render(widget, text: str, base_tag="ai_text"):
        """Insert `text` into a tk.Text widget with light markdown formatting.

        Handles ```fenced blocks```, `inline code`, **bold**, *italic*,
        `# ` headings and `- `/`1. ` lists. Terminal-safe (never raises)."""
        try:
            for tag in ("md_bold", "md_italic", "md_code", "md_head", "md_list"):
                if tag not in widget.tag_names():
                    widget.tag_config(tag)
            widget.tag_config("md_bold", font=("Consolas", 10, "bold"))
            widget.tag_config("md_italic", font=("Consolas", 10, "italic"))
            widget.tag_config("md_code", font=("Consolas", 9),
                              background="#1a1f2e", foreground="#7ee787")
            widget.tag_config("md_head", font=("Consolas", 11, "bold"),
                              foreground="#ff6b6b")
            widget.tag_config("md_list", foreground="#cba6f7")
        except Exception:
            pass

        try:
            text = str(text or "")
            lines = text.split("\n")
            i = 0
            while i < len(lines):
                line = lines[i]
                if line.strip().startswith("```"):
                    block = []
                    i += 1
                    while i < len(lines) and not lines[i].strip().startswith("```"):
                        block.append(lines[i])
                        i += 1
                    i += 1   # skip closing fence
                    widget.insert(tk.END, "\n".join(block) + "\n", "md_code")
                    continue
                stripped = line.strip()
                if stripped.startswith("# "):
                    widget.insert(tk.END, line.lstrip("#").strip() + "\n", "md_head")
                elif (stripped and stripped[0] in "-+*" and len(stripped) > 1 and stripped[1] == " "):
                    widget.insert(tk.END, "   " + line.strip() + "\n", "md_list")
                else:
                    _j = 0
                    while _j < len(stripped) and stripped[_j].isdigit():
                        _j += 1
                    if _j and _j + 1 < len(stripped) and stripped[_j] in ".)" and stripped[_j + 1] == " ":
                        widget.insert(tk.END, "   " + line.strip() + "\n", "md_list")
                    else:
                        NightmareAILoader._md_inline(widget, line + "\n", base_tag)
                i += 1
        except Exception:
            pass

    @staticmethod
    def _md_inline(widget, line: str, base_tag: str):
        """Insert one line, splitting inline code/bold/italic into tagged runs.

        Deliberately free of the ``re`` module (the runtime import seal removes
        it from module scope), so parsing is a plain character scan."""
        pos = 0
        i = 0
        n = len(line)
        try:
            while i < n:
                c = line[i]
                if c == "`":
                    end = line.find("`", i + 1)
                    if end < 0:
                        break
                    widget.insert(tk.END, line[pos:i], base_tag)
                    widget.insert(tk.END, line[i + 1:end], "md_code")
                    pos = i = end + 1
                    continue
                if c == "*":
                    if line.startswith("**", i):
                        end = line.find("**", i + 2)
                        if end < 0:
                            break
                        widget.insert(tk.END, line[pos:i], base_tag)
                        widget.insert(tk.END, line[i + 2:end], "md_bold")
                        pos = i = end + 2
                        continue
                    end = line.find("*", i + 1)
                    if end < 0:
                        break
                    widget.insert(tk.END, line[pos:i], base_tag)
                    widget.insert(tk.END, line[i + 1:end], "md_italic")
                    pos = i = end + 1
                    continue
                i += 1
        except Exception:
            return
        widget.insert(tk.END, line[pos:], base_tag)

    # === Chat History Save/Load ===
    
    def _save_chat_history(self):
        """Save all chat sessions to disk."""
        data = {
            "sessions": [s.to_dict() for s in self.chat_sessions],
            "active_tab": self.active_tab
        }
        
        save_path = self.save_dir / "chat_history.json"
        with open(save_path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        
        try:
            self._append_chat_jsonl()
        except Exception:
            pass
        self._append_system(f"💾 Chat history saved ({len(self.chat_sessions)} sessions)\n")
    
    def _load_chat_history(self):
        """Load saved chat history from disk."""
        save_path = self.save_dir / "chat_history.json"
        if not save_path.exists():
            return
        
        try:
            with open(save_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            
            self.chat_sessions = [
                ChatSession.from_dict(s) for s in data.get("sessions", [])
            ]
            self.active_tab = min(data.get("active_tab", 0), len(self.chat_sessions) - 1)
            
            if not self.chat_sessions:
                self.chat_sessions = [ChatSession(name="Chat 1")]
                self.active_tab = 0
            
            self._refresh_tabs()
            self._reload_chat_display()
            
        except Exception as e:
            print(f"Error loading chat history: {e}")

    def _export_chat_json(self):
        """Export every chat session to a single .json file (OpenAI style)."""
        export = {
            "app": "Nightmare Designs — AI Master Suite v13",
            "exported_at": time.time(),
            "sessions": [s.to_dict() for s in self.chat_sessions],
        }
        try:
            path = filedialog.asksaveasfilename(
                title="Export Chat (JSON)", defaultextension=".json",
                initialfile="nightmare_chat_export.json",
                filetypes=[("JSON", "*.json"), ("All files", "*.*")])
            if not path:
                return
            with open(path, "w", encoding="utf-8") as f:
                json.dump(export, f, indent=2, ensure_ascii=False)
            self._append_system(f"📦 Chat exported → {path}\n")
        except Exception as e:
            self._append_system(f"❌ Export failed: {e}\n")

    def _append_chat_jsonl(self):
        """Append any new messages to an append-only JSONL autosave.

        Uses each message's timestamp as a high-water mark so repeated calls
        never duplicate already-logged lines."""
        jsonl_path = self.save_dir / "nightmare_chat_autosave.jsonl"
        last_ts = 0.0
        if jsonl_path.is_file():
            try:
                with open(jsonl_path, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            row = json.loads(line)
                            last_ts = max(last_ts, float(row.get("timestamp", 0)))
                        except Exception:
                            continue
            except Exception:
                pass
        rows = []
        for si, session in enumerate(self.chat_sessions):
            for mi, msg in enumerate(session.messages):
                if float(msg.timestamp) <= last_ts:
                    continue
                rows.append({
                    "session": si,
                    "session_name": session.name,
                    "index": mi,
                    "role": getattr(msg, "role", "user"),
                    "content": getattr(msg, "content", ""),
                    "timestamp": msg.timestamp,
                })
        if not rows:
            return
        try:
            with open(jsonl_path, "a", encoding="utf-8") as f:
                for row in rows:
                    f.write(json.dumps(row, ensure_ascii=False) + "\n")
            try:
                self.output_queue.put(("system", f"💾 Autosaved {len(rows)} new message(s) → {jsonl_path.name}\n"))
            except Exception:
                pass
        except Exception as e:
            try:
                self.output_queue.put(("system", f"⚠️ JSONL autosave: {e}\n"))
            except Exception:
                pass

    def _recommend_model(self):
        """VRAM-aware model recommender: opens a dialog that ranks every
        discovered model against the free memory of each detected GPU."""
        def build():
            info = "🧠 MODEL RECOMMENDER\n"
            gpus = []
            try:
                from gpu_info import get_gpu_info
                gpus = get_gpu_info(force=True)
            except Exception:
                gpus = []
            if gpus:
                for g in gpus:
                    free_gb = float(g.get("free", 0)) / 1e9
                    total_gb = float(g.get("total", 0)) / 1e9
                    info += (f"GPU {g.get('index', 0)}: {g.get('name', '?')} — "
                             f"{free_gb:.1f} free / {total_gb:.1f} GB\n")
                best_free = max((float(g.get("free", 0)) for g in gpus), default=0.0)
                fused_free = best_free + max(
                    (float(g.get("free", 0)) for g in sorted(gpus, key=lambda r: r.get('index', 0))[:-1] or [-1]),
                    default=0.0)
            else:
                info += "No GPU detected (nvidia-smi) — using CPU-mode estimates.\n"
                best_free = 0.0
                fused_free = 0.0
            info += "\n"
            found = {}
            try:
                import ntmre_router
                found = ntmre_router.discover_models(os.path.dirname(os.path.abspath(__file__)))
            except Exception:
                found = {}
            rows = []
            for label, path in found.items():
                try:
                    size_bytes = os.path.getsize(path)
                except Exception:
                    size_bytes = 0
                size_gb = size_bytes / 1e9
                est_resident = size_gb + 1.2   # weights + KV/context headroom
                if gpus and best_free > 0:
                    fit = "single-GPU" if est_resident <= best_free * 0.92 else (
                          "fused-2GPU" if est_resident <= fused_free * 0.92 else "too big")
                else:
                    fit = "CPU (any)" if est_resident < 32 else "large/CPU"
                rows.append((fit, est_resident, size_gb, label))
            order = {"single-GPU": 0, "fused-2GPU": 1, "CPU (any)": 2, "large/CPU": 3, "too big": 4}
            rows.sort(key=lambda r: (order.get(r[0], 9), r[1]))
            for fit, est, size, label in rows[:40]:
                info += f"[{fit:10s}] {est:6.1f}GB (file {size:.1f}GB)  {label}\n"
            if not rows:
                info += "No models found in discovery paths.\n"
            info += ("\nEstimates: file size + ~1.2 GB KV/context headroom. "
                     "Fusion splits layers across 2 GPUs.\n")
            out.config(state=tk.NORMAL)
            out.delete("1.0", tk.END)
            out.insert("1.0", info)
            out.config(state=tk.DISABLED)
        w = tk.Toplevel(self.root)
        w.title("🧠 Model Recommender (VRAM)")
        w.geometry("760x560")
        w.configure(bg=COLORS["bg"])
        w.transient(self.root)
        tk.Label(w, text="MODEL RECOMMENDER — VRAM AWARE",
                 bg=COLORS["bg"], fg=COLORS["blood_bright"],
                 font=("Impact", 15)).pack(pady=(12, 4))
        out = tk.Text(w, bg=COLORS["bg_card"], fg=COLORS["matrix_green"],
                      font=("Consolas", 10), wrap=tk.WORD, state=tk.DISABLED)
        out.pack(fill=tk.BOTH, expand=True, padx=12, pady=12)
        tk.Button(w, text="🔄 Refresh", command=build, bg=COLORS["bg_card"],
                  fg=COLORS["matrix_green"], relief=tk.FLAT).pack(pady=(0, 12))
        build()

