    def _cfx_update_stats(self):
        """Forward to the admin panel's own refresh."""
        panel = getattr(self, "_brain_panel", None)
        if panel is not None:
            try:
                panel.refresh()
            except Exception:
                pass

    def _refresh_gate_status(self, _evt=None):
        """Update the sidebar Tools readout. Cheap; safe to call often."""
        try:
            lbl = getattr(self, "_gate_status_lbl", None)
            gate = getattr(self, "_tool_gate", None)
            if lbl is None or gate is None:
                return
            s = gate.stats()
            if s["persistent"]:
                txt, col = "Tools: ON (switch)", COLORS["matrix_green"]
            elif s["armed"]:
                txt, col = "Tools: armed - this turn only", COLORS["matrix_green"]
            else:
                txt, col = "Tools: off", COLORS["text_dim"]
            txt += "  |  %d used, %d blocked" % (s["totalCalls"], s["deniedCalls"])
            lbl.config(text=txt, fg=col)
        except Exception:
            pass

    def _refresh_brain_status(self, _evt=None):
        """
        Brain readout. Now admin-panel only (see _cfx_update_stats);
        kept as an alias so any older caller still works.
        """
        self._cfx_update_stats()

    def _stop_generation(self):
        self.is_generating = False
    
    def _clear_chat(self):
        self.chat_sessions[self.active_tab].messages.clear()
        self._reload_chat_display()
    
    def _on_enter(self, event):
        if not (event.state & 0x1):  # Not Shift
            self._send_message()
            return "break"
    
    # === Display Helpers ===
    
    def _append_system(self, text: str):
        self.chat_display.config(state=tk.NORMAL)
        self.chat_display.insert(tk.END, text, "system")
        self.chat_display.config(state=tk.DISABLED)
        self.chat_display.see(tk.END)
        
        session = self.chat_sessions[self.active_tab]
        session.messages.append(ChatMessage(role="system", content=text.strip()))
    
    def _append_user(self, text: str):
        self.chat_display.config(state=tk.NORMAL)
        self.chat_display.insert(tk.END, "You: ", "user_name")
        self.chat_display.insert(tk.END, text + "\n", "user_text")
        self.chat_display.config(state=tk.DISABLED)
        self.chat_display.see(tk.END)
    
    def _save_generated_file(self, filename: str, content: str):
        """Save a generated code file to disk with comprehensive file type support."""
        initial_file = filename or "program.py"
        ext = os.path.splitext(initial_file)[1].lower() or ".py"
        save_path = filedialog.asksaveasfilename(
            title=f"Download / Save Generated File ({initial_file})",
            initialfile=initial_file,
            defaultextension=ext,
            filetypes=[
                ("All Files", "*.*"),
                ("Python (*.py, *.pyw)", "*.py;*.pyw"),
                ("Windows Batch (*.bat, *.cmd)", "*.bat;*.cmd"),
                ("PowerShell (*.ps1)", "*.ps1"),
                ("Shell Script (*.sh, *.bash)", "*.sh;*.bash"),
                ("C / C++ Source (*.c, *.cpp, *.h, *.hpp)", "*.c;*.cpp;*.h;*.hpp"),
                ("C# Source (*.cs)", "*.cs"),
                ("Rust Source (*.rs)", "*.rs"),
                ("Go Source (*.go)", "*.go"),
                ("Java / Kotlin (*.java, *.kt)", "*.java;*.kt"),
                ("JavaScript / TypeScript (*.js, *.ts, *.jsx, *.tsx)", "*.js;*.ts;*.jsx;*.tsx"),
                ("Web (*.html, *.css, *.vue, *.svelte)", "*.html;*.css;*.vue;*.svelte"),
                ("Config & Data (*.json, *.yaml, *.yml, *.toml, *.xml, *.ini)", "*.json;*.yaml;*.yml;*.toml;*.xml;*.ini"),
                ("SQL & DB (*.sql)", "*.sql"),
                ("CUDA Source (*.cu, *.cuh)", "*.cu;*.cuh"),
                ("Markdown & Docs (*.md, *.txt, *.csv)", "*.md;*.txt;*.csv")
            ]
        )
        if save_path:
            try:
                with open(save_path, "w", encoding="utf-8") as f:
                    f.write(content)
                self._append_system(f"💾 File successfully saved to: {save_path}\n")
            except Exception as e:
                messagebox.showerror("Save Error", f"Failed to save file: {e}")

    def _save_all_generated_files(self, file_list: list):
        """Save all generated files into a selected destination folder."""
        if not file_list:
            return
        dest_folder = filedialog.askdirectory(title="Select Folder to Download All Generated Files")
        if not dest_folder:
            return
        saved_count = 0
        try:
            for fname, content in file_list:
                clean_fname = os.path.basename(fname)
                target_path = os.path.join(dest_folder, clean_fname)
                with open(target_path, "w", encoding="utf-8") as f:
                    f.write(content)
                saved_count += 1
            self._append_system(f"📦 Successfully saved all {saved_count} files into: {dest_folder}\n")
            messagebox.showinfo("Download Complete", f"All {saved_count} files have been saved to:\n{dest_folder}")
        except Exception as e:
            messagebox.showerror("Save All Error", f"Failed to save files: {e}")

    def _copy_generated_code(self, content: str, btn=None):
        """Copy generated code block to clipboard."""
        try:
            self.root.clipboard_clear()
            self.root.clipboard_append(content)
            if btn:
                btn.config(text="✓ Copied!")
                self.root.after(2000, lambda: btn.config(text="📋 Copy Code"))
        except Exception:
            pass

    def _append_ai(self, text: str):
        """Append an AI reply to the chat display with automatic multi-language detection & 1-click download buttons."""
        self.chat_display.config(state=tk.NORMAL)
        self.chat_display.insert(tk.END, "AI: ", "ai_name")

        # Map of language tags to file extensions
        lang_ext_map = {
            "python": ".py", "py": ".py", "pyw": ".pyw", "python3": ".py",
            "batch": ".bat", "bat": ".bat", "cmd": ".bat",
            "powershell": ".ps1", "ps1": ".ps1", "ps": ".ps1",
            "bash": ".sh", "sh": ".sh", "shell": ".sh", "zsh": ".sh",
            "c": ".c", "h": ".h",
            "cpp": ".cpp", "cxx": ".cpp", "cc": ".cpp", "c++": ".cpp", "hpp": ".hpp",
            "csharp": ".cs", "cs": ".cs",
            "rust": ".rs", "rs": ".rs",
            "go": ".go", "golang": ".go",
            "java": ".java", "kotlin": ".kt", "kt": ".kt", "scala": ".scala",
            "swift": ".swift", "php": ".php", "ruby": ".rb", "rb": ".rb",
            "lua": ".lua", "perl": ".pl", "pl": ".pl",
            "r": ".r", "julia": ".jl", "jl": ".jl", "dart": ".dart",
            "zig": ".zig", "nim": ".nim",
            "cuda": ".cu", "cu": ".cu", "cuh": ".cuh",
            "asm": ".asm", "assembly": ".asm", "nasm": ".asm", "masm": ".asm",
            "glsl": ".glsl", "hlsl": ".hlsl",
            "sql": ".sql", "mysql": ".sql", "pgsql": ".sql", "sqlite": ".sql",
            "html": ".html", "htm": ".html", "xhtml": ".html",
            "css": ".css", "scss": ".scss", "sass": ".sass", "less": ".less",
            "javascript": ".js", "js": ".js", "mjs": ".js", "cjs": ".js",
            "typescript": ".ts", "ts": ".ts",
            "jsx": ".jsx", "tsx": ".tsx", "react": ".jsx",
            "vue": ".vue", "svelte": ".svelte",
            "json": ".json", "jsonl": ".jsonl", "geojson": ".json",
            "yaml": ".yaml", "yml": ".yml",
            "toml": ".toml", "xml": ".xml", "svg": ".svg",
            "ini": ".ini", "cfg": ".cfg", "conf": ".conf", "env": ".env", "properties": ".properties",
            "csv": ".csv", "tsv": ".tsv",
            "markdown": ".md", "md": ".md",
            "text": ".txt", "txt": ".txt", "plain": ".txt", "log": ".log",
            "dockerfile": "Dockerfile", "docker": "Dockerfile",
            "cmake": "CMakeLists.txt", "cmakelists": "CMakeLists.txt",
            "makefile": "Makefile", "make": "Makefile"
        }

        code_pattern = re.compile(r'```([a-zA-Z0-9_\-\.\+:]*)\n([\s\S]*?)```')
        last_idx = 0
        file_count = 1
        all_generated_files = []

        for match in code_pattern.finditer(text):
            pre_text = text[last_idx:match.start()]
            if pre_text:
                self.chat_display.insert(tk.END, pre_text, "ai_text")

            raw_tag = (match.group(1) or "python").strip()
            code_content = match.group(2)

            # Check if tag explicitly specifies filename (e.g. ```python:server.py or ```json:package.json)
            tag_filename = None
            if ":" in raw_tag:
                tag_parts = raw_tag.split(":", 1)
                lang = tag_parts[0].lower().strip()
                tag_filename = tag_parts[1].strip()
            else:
                lang = raw_tag.lower()

            # Determine extension
            ext = lang_ext_map.get(lang, ".py" if not lang else f".{lang}")
            if ext in ["Dockerfile", "CMakeLists.txt", "Makefile"]:
                detected_filename = ext
            else:
                # Check if first line contains explicit filename comment
                first_line = code_content.split("\n")[0] if code_content else ""
                name_match = re.match(r'^(?:#|//|REM|::|/\*|<!--)\s*([a-zA-Z0-9_\-\.\+]+\.[a-zA-Z0-9]+)', first_line)
                if tag_filename:
                    detected_filename = tag_filename
                elif name_match:
                    detected_filename = name_match.group(1)
                else:
                    detected_filename = f"program_{file_count}{ext}"

            all_generated_files.append((detected_filename, code_content))

            # Render code block in chat
            self.chat_display.insert(tk.END, f"\n┌── 📁 {detected_filename} ({lang or 'code'}) ───────────────────────────\n", "system")
            self.chat_display.insert(tk.END, code_content + "\n└───", "code")

            # Action Frame with Download & Copy buttons
            card_frame = tk.Frame(self.chat_display, bg=COLORS["bg_card"], bd=1, relief=tk.SOLID, padx=6, pady=4)
            lbl = tk.Label(card_frame, text=f"File: {detected_filename}", bg=COLORS["bg_card"], fg=COLORS["matrix"], font=("Consolas", 9, "bold"))
            lbl.pack(side=tk.LEFT, padx=(2, 8))

            cur_code = code_content
            cur_name = detected_filename

            btn_dl = tk.Button(
                card_frame,
                text=f"⬇️ Download {detected_filename}",
                bg=COLORS["matrix"],
                fg="#000000",
                font=("Segoe UI", 9, "bold"),
                relief=tk.FLAT,
                cursor="hand2",
                command=lambda n=cur_name, c=cur_code: self._save_generated_file(n, c)
            )
            btn_dl.pack(side=tk.LEFT, padx=4)

            btn_cp = tk.Button(
                card_frame,
                text="📋 Copy Code",
                bg=COLORS["bg_panel"],
                fg=COLORS["text"],
                font=("Segoe UI", 8),
                relief=tk.FLAT,
                cursor="hand2"
            )
            btn_cp.config(command=lambda c=cur_code, b=btn_cp: self._copy_generated_code(c, b))
            btn_cp.pack(side=tk.LEFT, padx=4)

            self.chat_display.window_create(tk.END, window=card_frame)
            self.chat_display.insert(tk.END, "\n\n", "ai_text")

            file_count += 1
            last_idx = match.end()

        # If multiple files were generated, provide a "Save All Files" project button
        if len(all_generated_files) > 1:
            multi_frame = tk.Frame(self.chat_display, bg=COLORS["bg_panel"], bd=1, relief=tk.GROOVE, padx=8, pady=6)
            tk.Label(multi_frame, text=f"📦 Project Bundle: {len(all_generated_files)} files generated", bg=COLORS["bg_panel"], fg="#00ffff", font=("Segoe UI", 9, "bold")).pack(side=tk.LEFT, padx=(2, 10))
            
            btn_save_all = tk.Button(
                multi_frame,
                text="⬇️ Download All Files to Folder...",
                bg="#00ffff",
                fg="#000000",
                font=("Segoe UI", 9, "bold"),
                relief=tk.FLAT,
                cursor="hand2",
                command=lambda fl=all_generated_files: self._save_all_generated_files(fl)
            )
            btn_save_all.pack(side=tk.LEFT, padx=4)
            self.chat_display.window_create(tk.END, window=multi_frame)
            self.chat_display.insert(tk.END, "\n\n", "ai_text")

        # Insert remaining trailing text
        post_text = text[last_idx:]
        if post_text:
            self.chat_display.insert(tk.END, post_text + "\n\n", "ai_text")
        else:
            self.chat_display.insert(tk.END, "\n\n", "ai_text")

        self.chat_display.config(state=tk.DISABLED)
        self.chat_display.see(tk.END)

        session = self.chat_sessions[self.active_tab]
        session.messages.append(ChatMessage(role="assistant", content=text.strip()))

        # --- Memory writeback -------------------------------------------
        # Until now the Brain brain was read-only from the GUI: the chat
        # loop injected memories (build_prompt_context, above) but never
        # wrote a turn back. So the assistant could recall seven facts from June and
        # nothing else, because nothing ever put anything new in the store,
        # and a context rollover had nothing to resume from.
        #
        # This is the write half. It runs on the GUI thread, after the
        # assistant message is committed, so a slow or failing store write
        # can never stall generation or lose the visible reply.
        #
        # A follow-up turn is skipped: the text that preceded it was written
        # by the suite, not by Levi, so learning from it would store the
        # suite's own instructions as her memory of what the user said.
        if getattr(self, "_current_turn_is_followup", False):
            return
        self._remember_turn(session)

    def _ask_ai_summary(self, transcript):
        """Ask the loaded model to compress a block of transcript.

        Returns "" on any failure, so the caller falls back to the extractive
        path. Uses the same engine and tokenizer as normal chat, which is why
        it lives on the suite rather than in Brain -- Brain has no model.
        """
        try:
            model = getattr(self, "model", None)
            tok = getattr(self, "tokenizer", None)
            if model is None or tok is None:
                return ""
            instr = ("Summarise the conversation below into at most 6 short "
                     "factual bullet points. Keep names, decisions, numbers "
                     "and anything the user asked you to remember. No "
                     "preamble.\n\n" + transcript)
            ids = tok.encode(instr, add_bos=True)
            if not ids:
                return ""
            # Keep the summariser input well inside the window so it cannot
            # be the thing that overruns.
            room = int(getattr(model, "max_seq_len", 2048)) // 3
            if len(ids) > room:
                ids = ids[-room:]
            model.reset() if hasattr(model, "reset") else None
            out = []
            nxt = None
            for i, t in enumerate(ids):
                logits = model.forward(int(t), position=i)
                nxt = int(logits) if isinstance(logits, (int, float)) else\
                    int(__import__("numpy").argmax(logits))
                if i >= len(ids) - 1:
                    break
            if nxt is None:
                return ""
            eos = int(getattr(tok, "eos_id", 2))
            for step in range(160):
                if nxt == eos:
                    break
                try:
                    out.append(decode_token(tok, nxt))
                except Exception:
                    pass
                logits = model.forward(nxt, position=len(ids) + step)
                nxt = int(logits) if isinstance(logits, (int, float)) else\
                    int(__import__("numpy").argmax(logits))
            text = "".join(out).strip()
            return text if len(text) >= 20 else ""
        except Exception:
            return ""

    def _handoff_context(self, session, budget_tokens):
        """Fit the conversation into `budget_tokens`, spilling the overflow to
        Brain so nothing is lost when turns fall off the front.

        Returns the history list to feed the template, oldest first.

        The point is that dropping a turn from the visible window is not the
        same as forgetting it. Anything that falls off is summarised into the
        memory store first, so the next turn still retrieves it -- the
        conversation keeps moving without a seam. That is what makes a long
        chat possible instead of having her stop mid-thought when the KV
        cache fills.

        Falls back to silent truncation only if there is no brain at all.
        """
        msgs = [m for m in getattr(session, "messages", [])
                if getattr(m, "role", "") in ("user", "assistant")
                and str(getattr(m, "content", "")).strip()]
        # The current user message is appended separately by the template, so
        # exclude it here to avoid sending it twice.
        if msgs and getattr(msgs[-1], "role", "") == "user":
            msgs = msgs[:-1]

        tok = getattr(self, "tokenizer", None)
        brain = getattr(self, "_brain_state", None)

        def size(m):
            if tok is None:
                return max(1, len(str(getattr(m, "content", ""))) // 4)
            try:
                return len(tok.encode(str(getattr(m, "content", "")),
                                      add_bos=False))
            except Exception:
                return max(1, len(str(getattr(m, "content", ""))) // 4)

        total = sum(size(m) for m in msgs)
        if total <= budget_tokens:
            return [{"role": getattr(m, "role", ""),
                     "content": str(getattr(m, "content", ""))}
                    for m in msgs]

        # Drop from the front until it fits, remembering what fell off.
        drop_count = 0
        running = total
        for m in msgs:
            if running <= budget_tokens:
                break
            running -= size(m)
            drop_count += 1
        dropped = msgs[:drop_count]
        kept = msgs[drop_count:]

        if dropped and brain is not None and brain.is_enabled():
            try:
                transcript = "\n".join(
                    "%s: %s" % (getattr(m, "role", ""),
                                str(getattr(m, "content", ""))[:500])
                    for m in dropped)
                summary = self._ask_ai_summary(transcript) or\
                    self._extractive_summary(dropped)
                if summary:
                    brain.store.remember(
                        "Earlier in this conversation: " + summary,
                        category="conversation")
                    brain.store.save()
                    try:
                        self.output_queue.put(
                            ("system",
                             "\U0001F517 Handed off %d earlier message%s to "
                             "memory.\n" % (len(dropped),
                                            "" if len(dropped) == 1 else "s")))
                    except Exception:
                        pass
            except Exception:
                pass

        return [{"role": getattr(m, "role", ""),
                 "content": str(getattr(m, "content", ""))}
                for m in kept]

    def _extractive_summary(self, dropped):
        """No model needed: pull the most informative lines out of a block.

        Used when the model summariser is unavailable or returns nothing.
        Keeps the longest user lines, which is where durable intent lives,
        and caps the result so a huge block cannot bloat memory.
        """
        try:
            user_lines = [str(getattr(m, "content", "")).strip()
                          for m in dropped
                          if getattr(m, "role", "") == "user"]
            user_lines = [l for l in user_lines if len(l) >= 30]
            user_lines.sort(key=len, reverse=True)
            picked = user_lines[:4]
            if not picked:
                return ""
            text = " | ".join(p[:200] for p in picked)
            return text[:900]
        except Exception:
            return ""

    def _start_workbench_now(self):
        """Bring the workbench online off the UI thread.

        Used by the Start Workbench button when no turn is in flight, so the
        subprocess spawn and the catalogue read never block the Tk main loop.
        """
        def _emit(msg):
            try:
                if getattr(self, "is_generating", False):
                    self.output_queue.put(("system", msg))
                else:
                    self._append_system(msg)
            except Exception:
                pass

        _emit("\n🛠️ Starting workbench...\n")
        try:
            note = self._bring_workbench_online()
            if note:
                _emit(note)
        except Exception as exc:
            _emit("\n⚠️ Workbench failed to start: %s\n" % exc)

    def _lock_composer(self):
        """Stop the user typing into the composer.

        Called at the top of the dispatch window in _send_message, before the
        composer is cleared. Disabling a Tk Text does not erase its contents,
        so anything already typed survives and is where it was on unlock.

        Fails soft: a missing or destroyed widget must not stop a message.
        """
        self._composer_locked = True
        try:
            self.input_text.config(state=tk.DISABLED)
        except Exception:
            pass
        try:
            self.send_btn.config(state=tk.DISABLED, text=" ⏳ SENDING ")
        except Exception:
            pass

    def _unlock_composer(self):
        """Let the user type again.

        Called in a finally, so the box cannot be left disabled by an early
        return or an exception during dispatch.
        """
        self._composer_locked = False
        try:
            self.input_text.config(state=tk.NORMAL)
        except Exception:
            pass
        try:
            self.send_btn.config(state=tk.NORMAL, text=" ▶ SEND ")
        except Exception:
            pass

    def _fire_workbench_followup(self):
        """Give the assistant a turn of her own once the workbench is online.

        Called from the UI-thread poll loop. Guards against the two ways this
        could go wrong: a turn already running (ignore it), and the follow-up
        itself triggering another one (cap the chain), because a model that
        keeps asking for the workbench would otherwise loop forever.
        """
        if not getattr(self, "_followup_workbench", False):
            return
        self._followup_workbench = False

        if getattr(self, "is_generating", False):
            # Still busy. Put it back and try again on the next poll tick
            # rather than dropping a turn she was about to get.
            self._followup_workbench = True
            return

        chain = int(getattr(self, "_followup_chain", 0) or 0)
        if chain >= 3:
            # She has had three turns and still not finished. Stop handing
            # them out rather than spinning the GPU indefinitely.
            self._append_system(
                "\n🛠️ Workbench armed for your next message.\n")
            self._followup_chain = 0
            return

        self._followup_chain = chain + 1
        self._current_turn_is_followup = True
        try:
            # She has no idea the bench just came up -- from her side the
            # turn before it simply said "hold on". This is the prompt that
            # closes that gap and gives her something to act on.
            self._send_message(
                "[The workbench is online and ready. You have one tool this "
                "turn: wb.execute. Describe what you want done on this PC in "
                "plain English and call it.]",
                from_user=False)
        except Exception as exc:
            self._append_system("\n⚠️ Follow-up turn failed: %s\n" % exc)
        finally:
            self._current_turn_is_followup = False

    def _get_workbench(self):
        """The one Workbench instance for this suite.

        Workbench is not a singleton -- a fresh Workbench() spawns its own
        subprocess. Handing out a single shared instance means the catalogue
        read, the tool call, and the UI all talk to the same process instead
        of racing a second copy of it.
        """
        wb = getattr(self, "_workbench", None)
        if wb is None:
            from nightmare_workbench import Workbench
            wb = Workbench()
            self._workbench = wb
        return wb

    def _parse_tool_args(self, argstr: str, tool: str, wb) -> Dict[str, Any]:
        """
        Turn the model's argument string into a dict the workbench accepts.

        Two shapes are handled:

            <tool>fs.list(path="C:\\tmp")</tool>   -> {"path": "C:\\tmp"}
            <tool>fs.list(C:\\tmp)</tool>          -> {"path": "C:\\tmp"}

        Positional args are resolved against the tool's real signature, which
        `learn` returns on demand. Without that, positional calls had to be
        guessed at and the server would answer BAD_ARGS for a missing param.

        Returns {} when there is nothing to pass, which is correct for the
        many tools that take no arguments at all.
        """
        argstr = (argstr or "").strip()
        if not argstr:
            return {}

        # key=value form, split on commas that are not inside quotes.
        parts = re.findall(r'([A-Za-z_][A-Za-z0-9_]*)\s*=\s*("(?:[^"]*)"|\'(?:[^\']*)\'|[^,]+)',
                           argstr)
        if parts:
            out = {}
            for k, v in parts:
                v = v.strip()
                if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
                    v = v[1:-1]
                out[k] = v
            return out

        # Positional: map against the declared parameter names.
        raw = [p.strip().strip("\"'") for p in argstr.split(",") if p.strip()]
        if not raw:
            return {}

        names = self._tool_param_names(tool, wb)
        if not names:
            # Unknown signature. Pass the whole thing under the documented
            # "task" key when that is the tool's shape, else leave it alone.
            return {"task": argstr} if tool.endswith("query") else {}

        out = {}
        for i, val in enumerate(raw):
            if i < len(names):
                out[names[i]] = val
        return out

    def _tool_param_names(self, tool: str, wb) -> List[str]:
        """
        Parameter names for a tool, in order, from learn().

        The authoritative source is the `Signature:` line, which spells the
        parameters in positional order:

            Signature: run("fs.list", { path:string, recursive:boolean, ... })

        Parsing the prose bullets instead was a mistake -- the first real
        attempt returned nothing for most tools and invented "Returns" as a
        parameter for window.list, because both come from prose rather than
        from the declared signature.

        Cached: one round trip per tool, not one per call.
        """
        cache = getattr(self, "_tool_param_cache", None)
        if cache is None:
            cache = {}
            self._tool_param_cache = cache
        if tool in cache:
            return cache[tool]

        names: List[str] = []
        try:
            doc = str(wb.call("learn", {"tools": [tool]}, timeout=30) or "")

            # Preferred: the Signature line, ordered and complete.
            m = re.search(r'Signature:\s*run\(\s*"[^"]+"\s*,\s*\{([^}]*)\}', doc)
            if m:
                for part in m.group(1).split(","):
                    part = part.strip()
                    if not part:
                        continue
                    nm = part.split(":", 1)[0].strip().strip("`'\"")
                    if nm and re.fullmatch(r"[a-zA-Z_][a-zA-Z0-9_]*", nm):
                        names.append(nm)

            # Fallback: the bulleted parameter list, in order.
            if not names:
                for m2 in re.finditer(
                        r'^\s*-\s*`?([a-z_][a-z0-9_]*)`?\s*\(', doc,
                        re.MULTILINE):
                    nm = m2.group(1)
                    if nm not in names:
                        names.append(nm)
        except Exception:
            names = []

        cache[tool] = names
        return names

    def _resolve_workbench_tool(self, tname: str, targs: str):
        """
        Resolve a tool name the model actually emitted into a real call.

        This is the "works like everyone else" path: the model names a tool,
        we call it by that name. No find() re-ranking, no guessing at which
        tool was meant -- if it named window.list, window.list runs.

        Returns (ok, text). ok is False when the name is not a real tool, so
        the caller can fall back to the other resolutions.
        """
        name = (tname or "").strip().lower()
        if not name:
            return False, ""
        try:
            wb = self._get_workbench()
            if not wb.is_running():
                if not wb.start():
                    return False, ""
            args = self._parse_tool_args(targs, name, wb)
            out = wb.call("run", {"tool": name, "args": args}, timeout=120)
            if out is None:
                return True, ""
            return True, str(out)
        except Exception as exc:
            return True, "Workbench error: %s" % exc

    def _workbench_tool_index(self):
        """Build the real tool catalogue from the live workbench.

        The suite's own ALL_TOOLS table is a small gated subset with bare
        names ('fl_studio'). The workbench is the authority: it has the full
        set with real dotted names and English descriptions ('audio.play').
        So ask it, once per domain, and keep what it actually returns.

        Returns (domains, total) where domains is {domain: [tool, ...]}.
        Falls back to the suite's own table only if the workbench cannot
        answer, so her memory is never empty and never fictional.
        """
        try:
            from nightmare_tool_router import DOMAIN_KEYWORDS
        except Exception:
            DOMAIN_KEYWORDS = {}

        domains = {}
        try:
            wb = self._get_workbench()
            if not wb.is_running():
                wb.start()
            if wb.is_running():
                for dom in list(DOMAIN_KEYWORDS.keys()) + ["other"]:
                    probe = " ".join(DOMAIN_KEYWORDS.get(dom, [dom]))[:200]
                    try:
                        out = wb._call_tool(
                            "find", {"query": probe, "limit": 30}, timeout=25)
                    except Exception:
                        out = ""
                    if not out:
                        continue
                    for name in self._extract_workbench_names(out):
                        d = name.split(".")[0] if "." in name else dom
                        bucket = domains.setdefault(d, [])
                        if name not in bucket:
                            bucket.append(name)
        except Exception:
            domains = {}

        if not domains:
            # Workbench unavailable: fall back to the suite's own tool table
            # so the memory is still written from something that exists.
            try:
                import nightmare_tools_13
                for name in sorted(nightmare_tools_13.ALL_TOOLS.keys()):
                    domains.setdefault(name.split(".")[0], []).append(name)
            except Exception:
                domains = {}

        for d in domains:
            domains[d] = sorted(set(domains[d]))
        return domains, sum(len(v) for v in domains.values())

    def _extract_workbench_names(self, text):
        """Pull real tool names out of a workbench find() result.

        Matches dotted names only ('audio.play'). A bare word is not a tool,
        so accepting one would put things in her memory that cannot be run.
        """
        if not text:
            return []
        try:
            found = re.findall(r"^\s*-\s*([a-z_][a-z0-9_]*\.[a-z_][a-z0-9_]*)",
                               text, re.MULTILINE | re.IGNORECASE)
            if not found:
                found = re.findall(
                    r"\b([a-z_][a-z0-9_]*\.[a-z_][a-z0-9_]*)\b",
                    text, re.IGNORECASE)
            seen, out = set(), []
            for n in found:
                low = n.lower()
                if low not in seen:
                    seen.add(low)
                    out.append(low)
            return out
        except Exception:
            return []

    def _store_workbench_in_model_memory(self, domains, total):
        """Persist the tool list into model memory so it is retrievable on demand.

        Deliberately NOT injected into the prompt every turn -- she recalls
        it when a task actually needs it, which is what keeps the prompt cheap.
        """
        brain = getattr(self, "_brain_state", None)
        if brain is None:
            return 0
        try:
            # Count real growth, not remember()'s return value: remember()
            # also returns the surviving memory on a near-duplicate merge, so
            # counting its truthiness would overstate what was stored.
            before = len(brain.store.all())

            # The router's keyword map, for the same reason given below:
            # it is how she talks about a domain, not how the tool is named.
            try:
                from nightmare_tool_router import DOMAIN_KEYWORDS
            except Exception:
                DOMAIN_KEYWORDS = {}

            # Gaps the router's keyword list does not cover. "fl studio" has
            # no "studio" anywhere in the flstudio keywords, so the one domain
            # Levi asks about most often matched nothing at all. Kept short
            # and obvious on purpose -- these are lookup hooks, not new
            # behaviour.
            _DOMAIN_ALIASES = {
                "flstudio": ["studio", "daw", "fl", "music", "audio editing"],
                "fs": ["file", "files", "folder", "folders", "directory"],
                "screen": ["screenshot", "capture", "picture"],
                "wmi": ["temperature", "cpu", "gpu", "vram", "sensors",
                     "cpu load", "usage", "hardware monitor"],
                "audio": ["volume", "sound", "speaker"],
                "web": ["internet", "url", "website"],
                "process_ext": ["task manager", "running"],
                "window": ["app window", "foreground"],
                "input": ["mouse", "keyboard", "click", "type"],
                "shell": ["command prompt", "cmd", "powershell"],
                "registry": ["regedit", "windows registry"],
                "power": ["shutdown", "restart", "sleep"],
            }

            # One memory per domain, keyed on the domain word so a recall for
            # "audio" or "gaming" lands on the right list. The domain name is
            # repeated in the fact so the retrieval tokens carry it -- a fact
            # phrased only as a comma list would not match on its own name.
            for dom in sorted(domains):
                names = domains[dom]
                if not names:
                    continue
                # The router's English keywords go into the fact, not just
                # the domain slug. Tool names are dotted ('wmi.gpu_temp'),
                # which tokenises to "wmi", "gpu", "temp" -- so asking about
                # "gpu temperature" or "screenshot" matched nothing at all
                # and recall returned her the IoT notes instead. These words
                # are the link between how she talks and how tools are
                # named.
                kws = sorted(set(DOMAIN_KEYWORDS.get(dom, []))
                             | set(_DOMAIN_ALIASES.get(dom, [])))
                fact = ("Workbench %s tools (%d): %s. Use these when the task "
                        "is about %s or %s."
                        % (dom, len(names), ", ".join(names), dom,
                           ", ".join(kws)))
                brain.store.remember(fact, category="tool")

            # One index memory naming every domain, so a vague recall still
            # returns something. Reference data, so it is protected from decay
            # like every other tool row; its weight only decides ties.
            index = ("Workbench index: %d tools in %d domains: %s."
                     % (total, len(domains), ", ".join(sorted(domains))))
            # Slightly below the domain rows so a tie goes to the specific
            # list. The index names all 28 domains, so an ambiguous query
            # would otherwise resolve to the summary rather than a tool list.
            brain.store.remember(index, category="tool", weight=0.6)

            # --- How to summon it, and how to use it -------------------
            # Stored last on purpose. Everything above is only reachable
            # while the bench is up for that turn; these two survive it, so
            # a session later she still knows the gesture that starts the
            # bench and the exact syntax of a call. Without them the
            # knowledge is wiped the moment the armed prompt stops being
            # injected, which is the same gap as before but slower.
            #
            # Only reachable-relevant text: recall is relevance-led, so a
            # memory like this must contain the words someone would
            # actually ask it with ("tools", "summon", "use").
            how_summon = (
                "How to summon and use the tool workbench: say \"start the "
                "workbench\" in chat to summon it, or Levi can say it, or "
                "click Start Workbench in the sidebar. It comes online at the "
                "end of that turn, then you get a turn of your own. To call "
                "a tool, emit exactly <tool>wb.execute(task)</tool> where "
                "task is plain English for what you want done on this PC -- "
                "you never name the underlying tools and never guess at "
                "arguments."
            )
            # A hair above the domain rows. Only decides ties, so a query
            # naming a domain still lands on that domain's real list; a
            # vague "what tools do you have" now lands on this instead of an
            # arbitrary domain alphabetically nearest the front of the list.
            brain.store.remember(how_summon, category="tool", weight=1.8)

            brain.store.save(force=True)
            return max(0, len(brain.store.all()) - before)
        except Exception:
            return 0

    def _bring_workbench_online(self):
        """Start the workbench subprocess and arm the tool gate.

        Called from the end-of-turn hook, never before it. Returns a short
        note for the chat, or "" when the bench was already up.
        """
        try:
            wb = self._get_workbench()

            already = False
            try:
                already = bool(wb.is_running())
            except Exception:
                already = False

            if not already:
                ok = wb.start()
                if not ok:
                    return "\n⚠️ Workbench failed to start. See the workbench log.\n"

            domains, total = self._workbench_tool_index()
            written = self._store_workbench_in_model_memory(domains, total)

            # Arm for the next turn so her first tool call after a fresh
            # start is allowed rather than blocked by the gate.
            gate = getattr(self, "_tool_gate", None)
            if gate is not None:
                try:
                    gate.arm("workbench online", persistent=False)
                except Exception:
                    pass
            try:
                self._refresh_gate_status()
            except Exception:
                pass

            verb = "already online" if already else "online"
            note = ("\n🛠️ Workbench %s. %d tools across %d domains, "
                    "stored in memory (%d new entries).\n"
                    % (verb, total, len(domains), written))
            note += ("She recalls the tool list when a task needs it, "
                     "and the Tools switch is armed for her next turn.\n")
            return note
        except Exception as exc:
            return "\n⚠️ Workbench failed to start: %s\n" % exc

    def _remember_turn(self, session):
        """Hand the just-finished exchange to Brain.
        Finds the user message immediately preceding the assistant reply and
        passes the pair to observe_turn, which reinforces what was used,
        decays what was not, and extracts anything durable.

        Every failure path is swallowed: losing a memory is a nuisance, but
        an exception here would abort the render of a reply the user can
        already see.
        """
        brain = getattr(self, "_brain_state", None)
        if brain is None or not brain.is_enabled():
            return
        try:
            msgs = getattr(session, "messages", None) or []
            if len(msgs) < 2:
                return
            ai_text = str(getattr(msgs[-1], "content", "") or "")
            if getattr(msgs[-1], "role", "") != "assistant":
                return
            user_text = ""
            for m in reversed(msgs[:-1]):
                if getattr(m, "role", "") == "user":
                    user_text = str(getattr(m, "content", "") or "")
                    break
            if not user_text and not ai_text:
                return
            result = brain.observe_turn(user_text, ai_text)
            learned = int((result or {}).get("learned", 0))
            if learned:
                try:
                    self.output_queue.put(
                        ("system",
                         "\U0001F9E0 %d new memory item%s\n"
                         % (learned, "" if learned == 1 else "s")))
                except Exception:
                    pass
        except Exception:
            pass

    def _detect_gpus(self):
        """Detect GPUs in background."""
        self._detect_gpus_impl()
    def _on_gpu_mode_change(self, mode):
        import os
        if mode == "Auto Split":
            try:
                from nightmare_gpu_discovery import usable_accelerators
                _accs = usable_accelerators()
                if _accs:
                    os.environ["CUDA_VISIBLE_DEVICES"] = ",".join(str(d["index"]) for d in _accs)
                else:
                    os.environ["CUDA_VISIBLE_DEVICES"] = ""
            except Exception:
                os.environ["CUDA_VISIBLE_DEVICES"] = ""
            self.force_cpu.set(False)
        elif mode.startswith("GPU ") and " Only" in mode:
            try:
                # Parses e.g. "GPU 2 Only (NVIDIA)" -> "2"
                gpu_id = mode.split()[1]
                os.environ["CUDA_VISIBLE_DEVICES"] = str(gpu_id)
            except Exception:
                os.environ["CUDA_VISIBLE_DEVICES"] = "0"
            self.force_cpu.set(False)
        elif mode == "CPU Only":
            self.force_cpu.set(True)
        self._on_cpu_toggle()
        self._append_system(f"🎮 Hardware routed: {mode} (CUDA_VISIBLE_DEVICES={os.environ.get('CUDA_VISIBLE_DEVICES', 'CPU')})\n")
    def _on_cpu_toggle(self):
        """Handle CPU/GPU mode switch."""
        if self.force_cpu.get():
            try:
                import nightmare_hardware
                _r = nightmare_hardware.get_system_ram()
                _ram_txt = f"{_r['total_gb']} GB RAM"
            except Exception:
                _ram_txt = "System RAM"
            self.cpu_mode_label.config(text=f"Models will load on CPU ({_ram_txt})", fg=COLORS["warning"])
            self._append_system(f"🖥️ CPU-only mode enabled. Models will use {_ram_txt} dynamically.\n")
        else:
            self.cpu_mode_label.config(text="", fg=COLORS["text_dim"])
            self._append_system("⚡ GPU mode re-enabled. Next model load will use GPU.\n")
    
    def _detect_gpus_impl(self):
        """Detect GPUs in background across NVIDIA, AMD, and Intel."""
        def detect():
            try:
                from nightmare_gpu_discovery import usable_accelerators
                gpus = usable_accelerators()
                if gpus:
                    primary = gpus[0]
                    v_name = primary.get("vendor", "GPU").upper()
                    gpu_text = f"⚡ {v_name} Active ({len(gpus)} device{'s' if len(gpus) > 1 else ''})"
                    self.gpu_label.config(text=gpu_text, fg=COLORS["success"])
                else:
                    self.gpu_label.config(text="🖥️ CPU Inference Mode", fg=COLORS["warning"])
            except Exception as e:
                self.gpu_label.config(text=f"⚠️ GPU detect: {e}", fg=COLORS["text_dim"])
        
        threading.Thread(target=detect, daemon=True).start()
    
    def _init_system_monitor(self):
        """Initialize the system monitor."""
        try:
            from system_monitor import SystemMonitor
            self.sys_monitor = SystemMonitor()
            self.sys_monitor.start()
        except Exception as e:
            print(f"[Monitor] Failed to start: {e}")
            self.sys_monitor = None
    
    def _update_system_monitor(self):
        """Update system monitor UI every 1 second."""
        if self.sys_monitor:
            try:
                stats = self.sys_monitor.get_stats()
                
                # CPU / RAM
                cpu_text = f"CPU: {stats['cpu_percent']:.0f}% | RAM: {stats['ram_used_gb']:.1f}/{stats['ram_total_gb']:.1f} GB ({stats['ram_percent']:.0f}%)"
                self.cpu_ram_lbl.config(text=cpu_text)
                
                # GPU 0
                if stats["gpu_vram_used"] and len(stats["gpu_vram_used"]) > 0:
                    util0 = stats["gpu_util"][0] if stats["gpu_util"] else 0
                    vram0 = stats["gpu_vram_used"][0]
                    vtotal0 = stats["gpu_vram_total"][0]
                    vpct0 = stats["gpu_vram_percent"][0]
                    temp0 = stats["gpu_temp"][0] if stats["gpu_temp"] else 0
                    
                    self.gpu0_lbl.config(
                        text=f"GPU 0: {util0:.0f}% | VRAM: {vram0:.1f}/{vtotal0:.1f} GB | {temp0:.0f}°C"
                    )
                    self._draw_bar(self.gpu0_bar, vpct0)
                
                # GPU 1
                if stats["gpu_vram_used"] and len(stats["gpu_vram_used"]) > 1:
                    util1 = stats["gpu_util"][1] if len(stats["gpu_util"]) > 1 else 0
                    vram1 = stats["gpu_vram_used"][1]
                    vtotal1 = stats["gpu_vram_total"][1]
                    vpct1 = stats["gpu_vram_percent"][1]
                    temp1 = stats["gpu_temp"][1] if len(stats["gpu_temp"]) > 1 else 0
                    
                    self.gpu1_lbl.config(
                        text=f"GPU 1: {util1:.0f}% | VRAM: {vram1:.1f}/{vtotal1:.1f} GB | {temp1:.0f}°C"
                    )
                    self._draw_bar(self.gpu1_bar, vpct1)
                
                # Loading bar (driven by _load_model via self.model_loading_pct)
                loading_pct = getattr(self, 'model_loading_pct', 0)
                loading_status = getattr(self, 'model_loading_status', "")
                if 0 < loading_pct < 100:
                    self._draw_bar(self.loading_bar_canvas, loading_pct, color=COLORS["blood_bright"])
                    self.loading_status_lbl.config(text=loading_status or "Loading…", fg=COLORS["warning"])
                elif loading_pct >= 100:
                    self._draw_bar(self.loading_bar_canvas, 100, color=COLORS["success"])
                    self.loading_status_lbl.config(text=loading_status or "Ready", fg=COLORS["success"])
                else:
                    self._draw_bar(self.loading_bar_canvas, 0)
                    self.loading_status_lbl.config(text="Ready" if getattr(self, 'model_loaded', False) else "Idle", fg=COLORS["text_dim"])
                
            except Exception:
                pass
        
        # Update every 1 second
        if not self._running:
            return
        self._update_status_bar()
        self._monitor_id = self.root.after(1000, self._update_system_monitor)
    
    def _draw_bar(self, canvas, percent: float, color: str = None):
        """Draw a progress/usage bar on a canvas."""
        canvas.delete("all")
        width = canvas.winfo_width()
        if width <= 1:
            width = 260  # Default before first render
        height = canvas.winfo_height() or 8
        
        # Background
        canvas.create_rectangle(0, 0, width, height, fill=COLORS["bg"], outline="")
        
        # Fill color based on usage
        if color is None:
            if percent < 60:
                color = COLORS["matrix_green"]
            elif percent < 85:
                color = COLORS["warning"]
            else:
                color = COLORS["blood_bright"]
        
        # Fill bar
        fill_width = int((percent / 100) * width)
        if fill_width > 0:
            canvas.create_rectangle(0, 0, fill_width, height, fill=color, outline="")
    
    def _bar_mode(self, bar, mode):
        """Switch a ttk progressbar between determinate/indeterminate cleanly."""
        if getattr(self, '_bar_state', None) == mode:
            return
        try:
            bar.stop()
            bar.config(mode=mode, value=0)
        except Exception:
            pass
        self._bar_state = mode
    
    def _update_status_bar(self):
        """Drive the bar + info line right above the text box.

        Shows model-loading %, a pulsing/quantified indicator while the
        model is prefilling or generating a reply, and a short result
        summary when the reply finishes."""
        try:
            bar = getattr(self, 'status_progress', None)
            lbl = getattr(self, 'status_label', None)
            if bar is None or lbl is None:
                return
            phase = getattr(self, '_gen_phase', 'idle')
            loading_pct = int(getattr(self, 'model_loading_pct', 0) or 0)
            now = time.time()
            
            if phase == 'prefill':
                self._bar_mode(bar, 'determinate')
                # A cold engine requants each layer's tiles to resident Q8_0
                # on first access (one-time cost); surface that as progress
                # instead of a frozen "0/n tokens" so slow load is visible.
                _wl = getattr(self.model, 'warmup_progress', None)
                if _wl is not None:
                    try:
                        _w = _wl()
                    except Exception:
                        _w = None
                    if _w:
                        _wd, _wt, _dt = _w
                        if _wt and _wd < _wt:
                            bar.config(value=int(98 * _wd // _wt))
                            lbl.config(text=f"🔥 Warming layers {_wd}/{_wt}… {_dt}",
                                       fg=COLORS["warning"])
                            return
                n = getattr(self, '_gen_progress', 0)
                tot = max(1, getattr(self, '_gen_n_prompt', 1))
                bar.config(value=int(98 * n // tot))
                lbl.config(text=f"⚙  Prefill {n}/{tot} tokens…", fg=COLORS["warning"])
                return
            if phase == 'gen':
                prev = getattr(self, '_bar_state', 'determinate')
                self._bar_mode(bar, 'indeterminate')
                if prev != 'indeterminate':
                    bar.start(14)  # pulse while the model is thinking
                tok = getattr(self, '_gen_tokens', 0)
                mx = getattr(self, '_gen_max', 256) or 256
                sp = getattr(self, '_gen_speed', 0.0)
                sp_txt = f" · {sp:.1f} t/s" if sp > 0 else ""
                lbl.config(text=f"⚡ Generating {tok}/{mx} tok{sp_txt}", fg=COLORS["matrix_green"])
                return
            if phase == 'done':
                self._bar_mode(bar, 'determinate')
                bar.config(value=100)
                tok = getattr(self, '_gen_tokens', 0)
                sp = getattr(self, '_gen_speed', 0.0)
                lbl.config(text=f"✅ Done {tok} tok · {sp:.1f} t/s", fg=COLORS["success"])
                if now - getattr(self, '_gen_done_ts', 0) > 2.5:
                    self._gen_phase = 'idle'
                return
            
            # idle — reflect model loading state
            self._bar_mode(bar, 'determinate')
            if 0 < loading_pct < 100:
                bar.config(value=loading_pct)
                lbl.config(text=getattr(self, 'model_loading_status', '') or "Loading…", fg=COLORS["warning"])
            elif loading_pct >= 100:
                bar.config(value=100)
                lbl.config(text="✅ Model ready", fg=COLORS["success"])
            else:
                bar.config(value=0)
                lbl.config(text="No model loaded" if not getattr(self, 'model_loaded', False) else "Ready", fg=COLORS["text_dim"])
        except Exception:
            pass
    
