    def _run_script_hidden(self, cwd, script, *args, label="Script"):
        """Run a helper script hidden and pipe output to the Suite log."""
        import subprocess
        import threading
        if not cwd.exists():
            self._append_system(f"⚠️ {label} directory not found: {cwd}\n")
            return
        try:
            proc = subprocess.Popen(
                [sys.executable, str(script)] + list(args),
                cwd=str(cwd), env=os.environ.copy(),
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, bufsize=1,
                creationflags=subprocess.CREATE_NO_WINDOW)
            
            def _reader():
                try:
                    for line in proc.stdout:
                        line = line.rstrip()
                        if line:
                            self._append_system(f"[{label}] {line}\n")
                except Exception:
                    pass
            threading.Thread(target=_reader, daemon=True).start()
            self._append_system(f"🚀 {label} started (hidden).\n")
        except Exception as e:
            self._append_system(f"⚠️ {label} failed: {e}\n")
    
    
