def clear_ram_on_startup():
    """Clear RAM, purge VRAM on all GPUs, and terminate known rogue PIDs on startup."""
    import ctypes
    import subprocess as _sp
    import ctypes.wintypes
    
    _boot_log("Startup", "Performing full VRAM, RAM & Rogue PID Purge...")
    
    # --- 0) Kill known rogue orphan AI processes & lingering port holders ---
    try:
        import psutil
        _KNOWN_ROGUES = {
            "llama-server.exe", "ollama.exe", "ollama_llama_server.exe",
            "text-generation-server.exe", "vllm.exe", "ntmre.exe", "ntmre_gpu.exe",
            "ntmre_gemma4_gpu.exe", "ntmre_convert.exe", "ntmre_convert_gpu.exe",
            "undresstool.exe", "nightmaresuite.exe", "nightmaredirect.exe",
            "nightmarekickstarter.exe", "lm studio.exe", "lmstudio.exe"
        }
        _KEYWORDS = ["chat_gemma4.py", "stumpy.py"]
        cur_pid = os.getpid()
        killed = 0
        for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
            try:
                p_pid = proc.info['pid']
                p_name = (proc.info['name'] or '').lower()
                cmdline = " ".join(proc.info['cmdline'] or []).lower()
                if p_pid in (cur_pid, os.getppid()):
                    continue
                if p_name in _KNOWN_ROGUES or ("python" in p_name and any(kw in cmdline for kw in _KEYWORDS)):
                    proc.kill()
                    killed += 1
            except Exception:
                pass
        if killed > 0:
            _boot_log("Startup", f"Terminated {killed} rogue/orphaned AI processes.")
    except Exception as e:
        _boot_log("Startup", f"Process scan notice: {e}")

    # --- 1) Reset CUDA Primary Contexts on ALL GPUs (if available) ---
    if _has_gpu:
        try:
            cu = ctypes.CDLL("nvcuda.dll")
            if cu.cuInit(0) == 0:
                count = ctypes.c_int(0)
                cu.cuDeviceGetCount(ctypes.byref(count))
                for i in range(count.value):
                    dev = ctypes.c_int(0)
                    cu.cuDeviceGet(ctypes.byref(dev), i)
                    if hasattr(cu, "cuDevicePrimaryCtxReset"):
                        cu.cuDevicePrimaryCtxReset(dev.value)
                    try:
                        ctx = ctypes.c_void_p(0)
                        if cu.cuCtxCreate_v2(ctypes.byref(ctx), 0, dev.value) == 0:
                            free_b = ctypes.c_size_t(0)
                            total_b = ctypes.c_size_t(0)
                            cu.cuMemGetInfo_v2(ctypes.byref(free_b), ctypes.byref(total_b))
                            _boot_log("Startup", f"⚡ GPU {i} VRAM Cleared: {free_b.value / (1024**2):.1f} MB Free / {total_b.value / (1024**2):.1f} MB Total")
                            cu.cuCtxDestroy_v2(ctx)
                    except Exception:
                        pass
        except Exception:
            pass
    else:
        _t = os.environ.get('NIGHTMARE_CPU_THREADS', '6')
        _boot_log("Startup", f"🖥️ CPU Environment Confirmed (AVX2+FMA {_t}-Thread OpenMP)")

    # --- 2) Empty working sets of all processes (reclaim cached RAM) ---
    try:
        psapi = ctypes.WinDLL('psapi')
        kernel32 = ctypes.WinDLL('kernel32')
        
        PROCESS_QUERY_INFORMATION = 0x0400
        PROCESS_SET_QUOTA = 0x0100
        
        max_pids = 4096
        pids = (ctypes.wintypes.DWORD * max_pids)()
        bytes_returned = ctypes.wintypes.DWORD()
        psapi.EnumProcesses(ctypes.byref(pids), ctypes.sizeof(pids), ctypes.byref(bytes_returned))
        num_pids = bytes_returned.value // ctypes.sizeof(ctypes.wintypes.DWORD)
        
        cleared = 0
        for i in range(num_pids):
            pid = pids[i]
            if pid in (0, os.getpid()):
                continue
            h = kernel32.OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_SET_QUOTA, False, pid)
            if h:
                psapi.EmptyWorkingSet(h)
                kernel32.CloseHandle(h)
                cleared += 1
        
        _boot_log("Startup", f"Emptied working sets for {cleared} processes.")
    except Exception as e:
        _boot_log("Startup", f"Working set clear failed: {e}")
    
    # --- 3) Clear standby list (requires admin elevation) ---
    # OPT-IN ONLY: the previous behavior relaunched an elevated PowerShell
    # (`Start-Process powershell -Verb RunAs`) on EVERY launch when the app
    # wasn't already admin, which is what pops the UAC prompt at startup.
    # Now it only elevates when NIGHTMARE_STANDBY_CLEAR=1 is explicitly set.
    # Default = no UAC; the non-elevated working-set purge above still runs.
    if os.environ.get("NIGHTMARE_STANDBY_CLEAR", "").strip().lower() not in ("1", "true", "yes"):
        return
    try:
        ntdll = ctypes.WinDLL('ntdll')
        is_admin = ctypes.windll.shell32.IsUserAnAdmin()
        if not is_admin:
            _sp.Popen([
                "powershell", "-NoProfile", "-WindowStyle", "Hidden", "-Command",
                "Start-Process powershell -Verb RunAs -WindowStyle Hidden -ArgumentList "
                "'-NoProfile -Command "
                "Add-Type -TypeDefinition ''using System; using System.Runtime.InteropServices; "
                "public class SL { [DllImport(\"\"ntdll.dll\"\")] public static extern int "
                "NtSetSystemInformation(int c, IntPtr i, int l); }''; "
                "$p = [Marshal]::AllocHGlobal(4); [Marshal]::WriteInt32($p,4); "
                "[SL]::NtSetSystemInformation(80,$p,4); [Marshal]::FreeHGlobal($p)'"
            ])
            return
        
        cmd = ctypes.c_ulong(4)
        status = ntdll.NtSetSystemInformation(80, ctypes.byref(cmd), ctypes.sizeof(cmd))
        if status == 0:
            _boot_log("Startup", "Standby list cleared.")
    except Exception as e:
        _boot_log("Startup", f"Standby list clear failed: {e}")
    
    _boot_log("Startup", "Full VRAM & RAM purge complete.")


def main():
    """Entry point — license gate then launch."""
    script_dir = Path(__file__).parent
    if str(script_dir) not in sys.path:
        sys.path.insert(0, str(script_dir))
    
    clear_ram_on_startup()
    launch_app()


def _safe_print(msg: str) -> None:
    """Print even when frozen windowed mode leaves sys.stdout as None."""
    try:
        if sys.stdout is not None:
            print(msg, flush=True)
    except Exception:
        pass


if __name__ == "__main__":
    _crash_dir = Path(sys.executable).parent if getattr(sys, 'frozen', False) else Path(__file__).resolve().parent
    try:
        main()
    except SystemExit:
        raise
    except BaseException as e:
        import traceback
        err_msg = traceback.format_exc()
        # Write the crash log FIRST, before any print (windowed exes have
        # sys.stdout == None, so printing first would silently lose the report).
        try:
            with open(_crash_dir / "CRASH_LOG.txt", 'w', encoding='utf-8') as f:
                f.write(f"NIGHTMARE v13 CRASH\n{'='*40}\n{err_msg}")
        except Exception:
            pass
        try:
            _safe_print("\n\n" + "="*60)
            _safe_print("  NIGHTMARE AI LOADER v13 — CRASH REPORT")
            _safe_print("="*60)
            _safe_print(err_msg)
        except Exception:
            pass
        try:
            input("\n  Press Enter to close...")
        except Exception:
            pass
